32:       window.setTimeout(() => {
33:         go();
34:         window.setTimeout(() => setVeil(false), 80);
35:       }, 420);
36:     }
37: 
38:     function isActive(id) {
39:       return solo ? solo === id : Boolean(enabled[id]);
40:     }
41: 
42:     return { enabled, toggle, openElement, veil, solo, isActive };
43:   }, [enabled, motionOff, navigate, veil, solo]);
44: 
45:   return (
46:     <PrototypeContext.Provider value={api}>
