}

.filter-tabs button {
  font-size: 0.68rem;
  padding: 0.25rem 0.6rem;
  border-radius: 6px;
}

.protocols-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.6rem;
}

.proto-card {
  background: #08090C;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.65rem;
