.proto-card:hover { border-color: rgba(255, 62, 0, 0.4); }
.proto-name { font-size: 0.78rem; font-weight: 700; color: var(--stark); }
.proto-type { font-size: 0.65rem; color: var(--plasma); text-transform: uppercase; font-weight: 600; }
