import { useEffect, useMemo, useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { usePerf } from "../perf/PerfProvider.jsx";

// ---------------------------------------------------------------------------
// 1. PUMP.FUN: 3D Green & White Pill Capsule
// ---------------------------------------------------------------------------
function PumpFunPill() {
  const group = useRef(null);
  useFrame((state) => {
    if (!group.current) return;
    group.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.9) * 0.22;
    group.current.position.y = Math.sin(state.clock.elapsedTime * 1.6) * 0.035;
  });

  return (
    <group ref={group} rotation={[0.22, 0.15, -Math.PI / 4.2]}>
      {/* Lower Half - Mint Green */}
      <mesh position={[0, -0.09, 0]}>
        <cylinderGeometry args={[0.18, 0.18, 0.18, 32]} />
        <meshStandardMaterial
          color="#22C55E"
          roughness={0.2}
          metalness={0.15}
          emissive="#15803D"
          emissiveIntensity={0.2}
        />
      </mesh>
      <mesh position={[0, -0.18, 0]}>
        <sphereGeometry args={[0.18, 32, 16, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2]} />
        <meshStandardMaterial
          color="#22C55E"
          roughness={0.2}
          metalness={0.15}
          emissive="#15803D"
          emissiveIntensity={0.2}
        />
      </mesh>

      {/* Upper Half - Crisp White */}
      <mesh position={[0, 0.09, 0]}>
        <cylinderGeometry args={[0.18, 0.18, 0.18, 32]} />
        <meshStandardMaterial color="#FFFFFF" roughness={0.18} metalness={0.08} />
      </mesh>
      <mesh position={[0, 0.18, 0]}>
        <sphereGeometry args={[0.18, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2]} />
        <meshStandardMaterial color="#FFFFFF" roughness={0.18} metalness={0.08} />
      </mesh>

      {/* Dividing Seam Ring */}
      <mesh position={[0, 0, 0]}>
        <torusGeometry args={[0.183, 0.012, 12, 32]} />
        <meshStandardMaterial color="#0A0E14" roughness={0.4} />
      </mesh>

      {/* Gloss Specular Highlight Stripe */}
      <mesh position={[0.12, 0.06, 0.12]} rotation={[0, 0, -0.2]}>
        <capsuleGeometry args={[0.018, 0.08, 8, 16]} />
        <meshBasicMaterial color="#FFFFFF" opacity={0.65} transparent />
      </mesh>
    </group>
  );
}

// ---------------------------------------------------------------------------
// 2. METEORA DBC: 3D Sliced Aerodynamic Meteor
// ---------------------------------------------------------------------------
function MeteoraMeteor() {
  const group = useRef(null);

  const blades = useMemo(() => {
    function makeBlade(width, height, tailLen) {
      const shape = new THREE.Shape();
      shape.moveTo(-tailLen, -height / 2);
      shape.lineTo(width * 0.35, -height / 2);
      shape.quadraticCurveTo(width * 0.55, 0, width * 0.35, height / 2);
      shape.lineTo(-tailLen * 0.55, height / 2);
      shape.lineTo(-tailLen, -height / 2);
      return shape;
    }

    const extrudeSettings = {
      depth: 0.04,
      bevelEnabled: true,
      bevelSegments: 2,
      steps: 1,
      bevelSize: 0.008,
      bevelThickness: 0.008,
    };

    return [
      {
        shape: makeBlade(0.44, 0.085, 0.24),
        pos: [0.07, 0.16, 0.03],
        color: "#FF7700",
        emissive: "#FF6D00",
        settings: extrudeSettings,
      },
      {
        shape: makeBlade(0.56, 0.10, 0.38),
        pos: [0.03, 0.05, 0.01],
        color: "#FF3E00",
        emissive: "#EA580C",
        settings: extrudeSettings,
      },
      {
        shape: makeBlade(0.52, 0.10, 0.36),
        pos: [-0.02, -0.06, -0.01],
        color: "#E11D48",
        emissive: "#BE123C",
        settings: extrudeSettings,
      },
      {
        shape: makeBlade(0.38, 0.085, 0.26),
        pos: [-0.06, -0.16, -0.03],
        color: "#9333EA",
        emissive: "#7E22CE",
        settings: extrudeSettings,
      },
    ];
  }, []);

  useFrame((state) => {
    if (!group.current) return;
    group.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.8) * 0.18;
    group.current.position.y = Math.sin(state.clock.elapsedTime * 1.5 + 1) * 0.03;
  });

  return (
    <group ref={group} rotation={[0.1, 0, 0.55]}>
      {blades.map((b, idx) => (
        <mesh key={idx} position={b.pos}>
          <extrudeGeometry args={[b.shape, b.settings]} />
          <meshStandardMaterial
            color={b.color}
            emissive={b.emissive}
            emissiveIntensity={0.25}
            metalness={0.65}
            roughness={0.25}
          />
        </mesh>
      ))}
    </group>
  );
}

// ---------------------------------------------------------------------------
// 3. RAYDIUM: 3D Hexagonal Prism with Floating 'R' and Satellite Node
// ---------------------------------------------------------------------------
function RaydiumHex() {
  const group = useRef(null);

  const hexShape = useMemo(() => {
    const shape = new THREE.Shape();
    const R_out = 0.38;
    const R_in = 0.31;
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2;
      const x = Math.cos(a) * R_out;
      const y = Math.sin(a) * R_out;
      if (i === 0) shape.moveTo(x, y);
      else shape.lineTo(x, y);
    }
    shape.closePath();

    const hole = new THREE.Path();
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2;
      const x = Math.cos(a) * R_in;
      const y = Math.sin(a) * R_in;
      if (i === 0) hole.moveTo(x, y);
      else hole.lineTo(x, y);
    }
    hole.closePath();
    shape.holes.push(hole);
    return shape;
  }, []);

  useFrame((state) => {
    if (!group.current) return;
    group.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.9 + 2) * 0.2;
    group.current.position.y = Math.sin(state.clock.elapsedTime * 1.4 + 2) * 0.035;
  });

  return (
    <group ref={group}>
      {/* Outer Hexagonal Bezel */}
      <mesh position={[0, 0, -0.025]}>
        <extrudeGeometry
          args={[
            hexShape,
            { depth: 0.05, bevelEnabled: true, bevelThickness: 0.008, bevelSize: 0.008 },
          ]}
        />
        <meshStandardMaterial
          color="#38BDF8"
          emissive="#0284C7"
          emissiveIntensity={0.3}
          metalness={0.8}
          roughness={0.2}
        />
      </mesh>

      {/* Inner Geometric 'R' */}
      <group position={[0, 0, 0]}>
        {/* Vertical Spine */}
        <mesh position={[-0.08, 0, 0]}>
          <boxGeometry args={[0.055, 0.30, 0.04]} />
          <meshStandardMaterial
            color="#6366F1"
            emissive="#4F46E5"
            emissiveIntensity={0.3}
            metalness={0.7}
            roughness={0.25}
          />
        </mesh>
        {/* Top Horizontal Bar */}
        <mesh position={[-0.02, 0.125, 0]}>
          <boxGeometry args={[0.13, 0.05, 0.04]} />
          <meshStandardMaterial color="#6366F1" emissive="#4F46E5" emissiveIntensity={0.3} />
        </mesh>
        {/* Center Horizontal Bar */}
        <mesh position={[-0.02, 0.02, 0]}>
          <boxGeometry args={[0.12, 0.045, 0.04]} />
          <meshStandardMaterial color="#6366F1" emissive="#4F46E5" emissiveIntensity={0.3} />
        </mesh>
        {/* Upper Right Loop */}
        <mesh position={[0.05, 0.072, 0]}>
          <boxGeometry args={[0.045, 0.07, 0.04]} />
          <meshStandardMaterial color="#6366F1" emissive="#4F46E5" emissiveIntensity={0.3} />
        </mesh>
        {/* Diagonal Leg */}
        <mesh position={[0.04, -0.08, 0]} rotation={[0, 0, -0.65]}>
          <boxGeometry args={[0.05, 0.18, 0.04]} />
          <meshStandardMaterial color="#6366F1" emissive="#4F46E5" emissiveIntensity={0.3} />
        </mesh>
      </group>

      {/* Top-Right Satellite Hexagon Node */}
      <mesh position={[0.34, 0.20, 0]} rotation={[0, 0, Math.PI / 6]}>
        <cylinderGeometry args={[0.04, 0.04, 0.04, 6]} />
        <meshStandardMaterial
          color="#C084FC"
          emissive="#A855F7"
          emissiveIntensity={1.2}
          metalness={0.6}
        />
      </mesh>
    </group>
  );
}

// ---------------------------------------------------------------------------
// 4. BAGS: 3D Lime Green Money Bag with Black '$'
// ---------------------------------------------------------------------------
function BagsMoneyBag() {
  const group = useRef(null);
  useFrame((state) => {
    if (!group.current) return;
    group.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.85 + 3) * 0.2;
    group.current.position.y = Math.sin(state.clock.elapsedTime * 1.5 + 3) * 0.035;
  });

  return (
    <group ref={group}>
      {/* Plump Bag Belly */}
      <mesh position={[0, -0.06, 0]} scale={[1.15, 0.96, 0.92]}>
        <sphereGeometry args={[0.26, 32, 24]} />
        <meshStandardMaterial
          color="#00E676"
          emissive="#16A34A"
          emissiveIntensity={0.2}
          roughness={0.32}
          metalness={0.12}
        />
      </mesh>

      {/* Cinched Neck Tie */}
      <mesh position={[0, 0.16, 0]}>
        <torusGeometry args={[0.12, 0.024, 12, 24]} />
        <meshStandardMaterial color="#14532D" roughness={0.4} metalness={0.2} />
      </mesh>

      {/* Flared Pouch Opening */}
      <mesh position={[0, 0.25, 0]} rotation={[Math.PI, 0, 0]}>
        <coneGeometry args={[0.17, 0.13, 16, 1, true]} />
        <meshStandardMaterial
          color="#00E676"
          emissive="#16A34A"
          emissiveIntensity={0.15}
          roughness={0.35}
          side={THREE.DoubleSide}
        />
      </mesh>
      <mesh position={[0, 0.31, 0]}>
        <torusGeometry args={[0.165, 0.016, 8, 24]} />
        <meshStandardMaterial color="#00E676" roughness={0.3} />
      </mesh>

      {/* Embossed Bold Black '$' on Belly */}
      <group position={[0, -0.06, 0.22]}>
        {/* Vertical Center Spine */}
        <mesh position={[0, 0, 0]}>
          <boxGeometry args={[0.03, 0.24, 0.03]} />
          <meshStandardMaterial color="#08090C" roughness={0.5} />
        </mesh>
        {/* Top Horizontal Bar */}
        <mesh position={[0, 0.065, 0]}>
          <boxGeometry args={[0.13, 0.032, 0.03]} />
          <meshStandardMaterial color="#08090C" roughness={0.5} />
        </mesh>
        {/* Top-Left Curve */}
        <mesh position={[-0.05, 0.035, 0]}>
          <boxGeometry args={[0.032, 0.045, 0.03]} />
          <meshStandardMaterial color="#08090C" roughness={0.5} />
        </mesh>
        {/* Middle Crossbar */}
        <mesh position={[0, 0, 0.005]}>
          <boxGeometry args={[0.13, 0.032, 0.03]} />
          <meshStandardMaterial color="#08090C" roughness={0.5} />
        </mesh>
        {/* Bottom-Right Curve */}
        <mesh position={[0.05, -0.035, 0]}>
          <boxGeometry args={[0.032, 0.045, 0.03]} />
          <meshStandardMaterial color="#08090C" roughness={0.5} />
        </mesh>
        {/* Bottom Horizontal Bar */}
        <mesh position={[0, -0.065, 0]}>
          <boxGeometry args={[0.13, 0.032, 0.03]} />
          <meshStandardMaterial color="#08090C" roughness={0.5} />
        </mesh>
      </group>
    </group>
  );
}

// ---------------------------------------------------------------------------
// CAROUSEL RIG
// ---------------------------------------------------------------------------
const VENUE_ACCENTS = ["#22C55E", "#FF3E00", "#38BDF8", "#00E676"];

function Rig({ focus }) {
  const group = useRef(null);
  const target = useRef(0);
  const { low } = usePerf();

  useEffect(() => {
    // Bring focused item to angle 0 (front facing camera)
    target.current = -focus * (Math.PI / 2);
  }, [focus]);

  useFrame((state) => {
    const node = group.current;
    if (!node) return;
    node.rotation.y += (target.current - node.rotation.y) * 0.09;
    node.rotation.x = state.pointer.y * 0.12;
    if (low) state.invalidate();
  });

  return (
    <group ref={group}>
      {[0, 1, 2, 3].map((index) => {
        const angle = (index / 4) * Math.PI * 2;
        const x = Math.sin(angle) * 1.25;
        const z = Math.cos(angle) * 1.25;
        const accent = VENUE_ACCENTS[index];

        return (
          <group key={index} position={[x, 0, z]}>
            {/* 3D Model according to venue */}
            {index === 0 && <PumpFunPill />}
            {index === 1 && <MeteoraMeteor />}
            {index === 2 && <RaydiumHex />}
            {index === 3 && <BagsMoneyBag />}

            {/* Glowing Accent Pedestal Ring Underneath */}
            <mesh position={[0, -0.46, 0]} rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[0.26, 0.32, 32]} />
              <meshBasicMaterial
                color={accent}
                transparent
                opacity={focus === index ? 0.6 : 0.15}
              />
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

export default function VenueScene({ onReady, focus = 0 }) {
  const { low } = usePerf();
  return (
    <Canvas
      dpr={low ? 1 : [1, 1.5]}
      frameloop={low ? "demand" : "always"}
      gl={{ antialias: !low, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [0, 0.45, 3.4], fov: 42 }}
      onCreated={({ gl, invalidate }) => {
        gl.setClearColor("#0D1117", 1);
        onReady?.();
        invalidate();
      }}
    >
      <ambientLight intensity={0.7} />
      <directionalLight position={[3, 4, 3]} intensity={2.2} />
      <directionalLight position={[-3, 2, -1]} intensity={0.8} color="#38BDF8" />
      <pointLight position={[0, -0.2, 1.8]} intensity={1.2} color="#FF7700" />
      <Rig focus={focus} />
    </Canvas>
  );
}

