import { useMemo, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { EffectComposer, Bloom } from "@react-three/postprocessing";
import * as THREE from "three";
import { usePerf } from "../perf/PerfProvider.jsx";

// ---------------------------------------------------------------------------
// Rising Market Spark Particles
// ---------------------------------------------------------------------------
function SparkField({ pumpActive, count = 90 }) {
  const pointsRef = useRef(null);
  const { low } = usePerf();
  const actualCount = low ? Math.floor(count * 0.35) : count;

  const [positions, velocities, colors] = useMemo(() => {
    const pos = new Float32Array(actualCount * 3);
    const vel = new Float32Array(actualCount);
    const col = new Float32Array(actualCount * 3);

    const c1 = new THREE.Color("#31E3AC");
    const c2 = new THREE.Color("#22C55E");
    const c3 = new THREE.Color("#FFFFFF");
    const cGold = new THREE.Color("#F59E0B");

    for (let i = 0; i < actualCount; i++) {
      // Cylinder radius around candle
      const rad = 0.2 + Math.random() * 0.65;
      const angle = Math.random() * Math.PI * 2;
      pos[i * 3] = Math.cos(angle) * rad;
      pos[i * 3 + 1] = -1.2 + Math.random() * 2.8;
      pos[i * 3 + 2] = Math.sin(angle) * rad;

      vel[i] = 0.012 + Math.random() * 0.035;

      const pick = Math.random();
      const chosen = pick > 0.8 ? c3 : pick > 0.6 ? cGold : pick > 0.3 ? c1 : c2;
      col[i * 3] = chosen.r;
      col[i * 3 + 1] = chosen.g;
      col[i * 3 + 2] = chosen.b;
    }
    return [pos, vel, col];
  }, [actualCount, low]);

  useFrame((_, delta) => {
    if (!pointsRef.current) return;
    const geo = pointsRef.current.geometry;
    const posAttr = geo.attributes.position;
    const speedMult = pumpActive ? 3.5 : 1.0;

    for (let i = 0; i < actualCount; i++) {
      let y = posAttr.getY(i) + velocities[i] * (delta * 60) * speedMult;
      if (y > 1.8) {
        y = -1.2 - Math.random() * 0.3;
      }
      posAttr.setY(i, y);
    }
    posAttr.needsUpdate = true;
    if (low) geo.attributes.position.needsUpdate = true;
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-color" args={[colors, 3]} />
      </bufferGeometry>
      <pointsMaterial
        size={low ? 0.04 : 0.03}
        vertexColors
        transparent
        opacity={0.85}
        sizeAttenuation
      />
    </points>
  );
}

// ---------------------------------------------------------------------------
// Resistance Breakthrough Rings
// ---------------------------------------------------------------------------
function ResistancePlanes({ candleHeight }) {
  const levels = [-0.6, 0.0, 0.6, 1.2];
  return (
    <group position={[0, 0, 0]}>
      {levels.map((y, idx) => {
        const breached = candleHeight > y;
        return (
          <group key={idx} position={[0, y, 0]}>
            {/* Horizontal Grid Frame */}
            <mesh rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[0.55, 0.58, 36]} />
              <meshBasicMaterial
                color={breached ? "#31E3AC" : "#1C2533"}
                transparent
                opacity={breached ? 0.45 : 0.15}
              />
            </mesh>
            {/* Breakthrough Crosshairs */}
            {breached && (
              <mesh rotation={[-Math.PI / 2, 0, 0]}>
                <ringGeometry args={[0.35, 0.36, 24]} />
                <meshBasicMaterial color="#22C55E" transparent opacity={0.3} />
              </mesh>
            )}
          </group>
        );
      })}
    </group>
  );
}

// ---------------------------------------------------------------------------
// Towering 3D God Candle
// ---------------------------------------------------------------------------
function GodCandle({ pumpActive, onTriggerPump }) {
  const group = useRef(null);
  const candleMesh = useRef(null);
  const currentHeight = useRef(1.4);
  const targetHeight = useRef(2.1);
  const pulseRef = useRef(0);
  const shockwaveRef = useRef(null);

  const { low } = usePerf();

  useFrame((state, delta) => {
    pulseRef.current += delta;

    // Pump burst vs idle breathing
    const baseTarget = pumpActive ? 2.55 : 2.05 + Math.sin(pulseRef.current * 2.2) * 0.15;
    targetHeight.current = baseTarget;

    // Smooth spring-like lerp to target height
    currentHeight.current += (targetHeight.current - currentHeight.current) * 0.12;
    const h = currentHeight.current;

    if (candleMesh.current) {
      candleMesh.current.scale.set(1, h, 1);
      // Anchor base at -0.9, so expanding height moves top upward!
      candleMesh.current.position.y = -0.9 + h / 2;
    }

    // Shockwave expansion on pump
    if (shockwaveRef.current) {
      if (pumpActive) {
        shockwaveRef.current.scale.x += delta * 4;
        shockwaveRef.current.scale.y += delta * 4;
        shockwaveRef.current.material.opacity = Math.max(
          0,
          shockwaveRef.current.material.opacity - delta * 1.5
        );
      } else {
        shockwaveRef.current.scale.set(0.1, 0.1, 0.1);
        shockwaveRef.current.material.opacity = 0.8;
      }
    }

    // Parallax mouse tilt
    const node = group.current;
    if (node) {
      const targetY = state.pointer.x * 0.35;
      const targetX = state.pointer.y * 0.15;
      node.rotation.y += (targetY - node.rotation.y) * 0.08;
      node.rotation.x += (targetX - node.rotation.x) * 0.08;
    }

    if (low) state.invalidate();
  });

  const candleTopY = -0.9 + currentHeight.current;

  return (
    <group ref={group} position={[0, 0, 0]} onClick={onTriggerPump}>
      {/* Lower Wick (Tail into the abyss) */}
      <mesh position={[0, -1.1, 0]}>
        <cylinderGeometry args={[0.016, 0.016, 0.42, 16]} />
        <meshStandardMaterial
          color="#15803D"
          emissive="#16A34A"
          emissiveIntensity={0.5}
        />
      </mesh>

      {/* Main Emerald God Candle Body */}
      <mesh ref={candleMesh} position={[0, 0.15, 0]}>
        <boxGeometry args={[0.36, 1, 0.36]} />
        <meshStandardMaterial
          color="#22C55E"
          emissive="#15803D"
          emissiveIntensity={pumpActive ? 0.95 : 0.65}
          metalness={0.25}
          roughness={0.12}
        />
      </mesh>

      {/* Luminous Neon Edge Highlights */}
      <mesh
        position={[0, -0.9 + currentHeight.current / 2, 0]}
        scale={[1.01, currentHeight.current, 1.01]}
      >
        <boxGeometry args={[0.36, 1, 0.36]} />
        <meshBasicMaterial color="#86EFAC" wireframe transparent opacity={0.35} />
      </mesh>

      {/* Upper Wick Piercing the Heavens */}
      <mesh position={[0, candleTopY + 0.3, 0]}>
        <cylinderGeometry args={[0.016, 0.016, 0.6, 16]} />
        <meshStandardMaterial
          color="#86EFAC"
          emissive="#31E3AC"
          emissiveIntensity={1.2}
        />
      </mesh>

      {/* Apex Spark Orb (High Water Mark) */}
      <group position={[0, candleTopY + 0.6, 0]}>
        <mesh>
          <sphereGeometry args={[0.05, 16, 16]} />
          <meshStandardMaterial
            color="#FFFFFF"
            emissive="#31E3AC"
            emissiveIntensity={2.5}
          />
        </mesh>
        {/* Pulsing Corona Halo */}
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.06, 0.12, 24]} />
          <meshBasicMaterial
            color="#31E3AC"
            transparent
            opacity={pumpActive ? 0.9 : 0.5}
          />
        </mesh>
      </group>

      {/* Resistance Levels Grid */}
      <ResistancePlanes candleHeight={candleTopY} />

      {/* Breakthrough Shockwave Ring */}
      <mesh
        ref={shockwaveRef}
        position={[0, candleTopY, 0]}
        rotation={[-Math.PI / 2, 0, 0]}
      >
        <ringGeometry args={[0.3, 0.35, 32]} />
        <meshBasicMaterial color="#31E3AC" transparent opacity={0.8} />
      </mesh>

      {/* Market Sparks */}
      <SparkField pumpActive={pumpActive} count={low ? 35 : 100} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Scene Root
// ---------------------------------------------------------------------------
export default function IntakeScene({ onReady }) {
  const { low, post } = usePerf();
  const [pumpActive, setPumpActive] = useState(false);

  function triggerPump() {
    setPumpActive(true);
    setTimeout(() => setPumpActive(false), 950);
  }

  return (
    <Canvas
      dpr={low ? 1 : [1, 1.5]}
      frameloop={low ? "demand" : "always"}
      gl={{ antialias: !low, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [0, 0.2, 3.4], fov: 42 }}
      onCreated={({ gl, invalidate }) => {
        gl.setClearColor("#0D1117", 1);
        onReady?.();
        invalidate();
      }}
    >
      <ambientLight intensity={0.65} />
      <directionalLight position={[3, 4, 3]} intensity={2.6} color="#FFFFFF" />
      <directionalLight position={[-3, -1, 2]} intensity={1.2} color="#15803D" />
      <pointLight position={[0, 1.5, 1]} intensity={2.0} color="#31E3AC" />

      <GodCandle pumpActive={pumpActive} onTriggerPump={triggerPump} />

      {post && (
        <EffectComposer disableNormalPass multisampling={0}>
          <Bloom
            intensity={0.65}
            luminanceThreshold={0.2}
            luminanceSmoothing={0.3}
            mipmapBlur
          />
        </EffectComposer>
      )}
    </Canvas>
  );
}

