import { useEffect, useMemo, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { EffectComposer, Bloom } from "@react-three/postprocessing";
import * as THREE from "three";
import { usePerf } from "../perf/PerfProvider.jsx";

// ---------------------------------------------------------------------------
// Historical Consolidating Candlesticks (Creates genuine market scale)
// ---------------------------------------------------------------------------
const HISTORICAL_CANDLES = [
  { x: -1.70, open: -0.48, close: -0.42, high: -0.38, low: -0.54, green: true, vol: 0.08 },
  { x: -1.40, open: -0.42, close: -0.50, high: -0.39, low: -0.55, green: false, vol: 0.12 },
  { x: -1.10, open: -0.50, close: -0.44, high: -0.40, low: -0.53, green: true, vol: 0.09 },
  { x: -0.80, open: -0.44, close: -0.54, high: -0.41, low: -0.58, green: false, vol: 0.15 },
  { x: -0.50, open: -0.54, close: -0.46, high: -0.42, low: -0.56, green: true, vol: 0.11 },
  { x: -0.20, open: -0.46, close: -0.40, high: -0.34, low: -0.48, green: true, vol: 0.14 },
  { x: 0.10, open: -0.40, close: -0.45, high: -0.36, low: -0.47, green: false, vol: 0.10 },
];

function HistoricalChart() {
  return (
    <group position={[0, 0, 0]}>
      {HISTORICAL_CANDLES.map((c, i) => {
        const bodyHeight = Math.max(0.04, Math.abs(c.close - c.open));
        const bodyY = (c.open + c.close) / 2;
        const wickHeight = Math.max(0.1, c.high - c.low);
        const wickY = (c.high + c.low) / 2;
        const color = c.green ? "#22C55E" : "#F43F5E";
        const emissive = c.green ? "#15803D" : "#BE123C";

        return (
          <group key={i} position={[c.x, 0, 0]}>
            {/* Candle Body */}
            <mesh position={[0, bodyY, 0]}>
              <boxGeometry args={[0.16, bodyHeight, 0.12]} />
              <meshStandardMaterial
                color={color}
                emissive={emissive}
                emissiveIntensity={0.35}
                roughness={0.25}
                metalness={0.2}
              />
            </mesh>

            {/* Candle Wick */}
            <mesh position={[0, wickY, 0]}>
              <cylinderGeometry args={[0.008, 0.008, wickHeight, 8]} />
              <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={0.5} />
            </mesh>

            {/* Bottom Volume Bar */}
            <mesh position={[0, -0.95 + c.vol / 2, 0]}>
              <boxGeometry args={[0.16, c.vol, 0.12]} />
              <meshStandardMaterial
                color={color}
                emissive={emissive}
                emissiveIntensity={0.2}
                transparent
                opacity={0.65}
              />
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

// ---------------------------------------------------------------------------
// Chart Grid & Shattered Resistance Levels
// ---------------------------------------------------------------------------
function ChartGridLines({ candleHeight }) {
  const levels = [
    { y: -0.95, label: "BASE", color: "#334155" },
    { y: -0.42, label: "BREAKOUT ($0.05)", color: "#475569" },
    { y: 0.30, label: "RESISTANCE 1 ($0.50)", color: "#059669" },
    { y: 0.95, label: "RESISTANCE 2 ($2.00)", color: "#10B981" },
    { y: 1.60, label: "ALL-TIME HIGH ($10.00+)", color: "#31E3AC" },
  ];

  return (
    <group position={[0, 0, -0.15]}>
      {levels.map((lvl, idx) => {
        const breached = candleHeight > lvl.y;
        return (
          <group key={idx} position={[0, lvl.y, 0]}>
            {/* Horizontal Grid Line */}
            <mesh>
              <boxGeometry args={[4.4, 0.008, 0.008]} />
              <meshBasicMaterial
                color={breached ? lvl.color : "#1E293B"}
                transparent
                opacity={breached ? 0.75 : 0.3}
              />
            </mesh>
          </group>
        );
      })}

      {/* Baseline Ground Plane with Grid Texture */}
      <mesh position={[0, -0.96, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[4.6, 2.2]} />
        <meshBasicMaterial color="#0A0E17" />
      </mesh>
      <gridHelper
        args={[4.6, 16, "#1E293B", "#0F172A"]}
        position={[0, -0.955, 0]}
      />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Ascending Rocket Fuel Market Sparks
// ---------------------------------------------------------------------------
function MarketSparkParticles({ count = 120, pumpActive }) {
  const pointsRef = useRef(null);
  const { low } = usePerf();
  const actualCount = low ? Math.floor(count * 0.35) : count;

  const [positions, speeds, colors] = useMemo(() => {
    const pos = new Float32Array(actualCount * 3);
    const spd = new Float32Array(actualCount);
    const col = new Float32Array(actualCount * 3);

    const cNeon = new THREE.Color("#31E3AC");
    const cGreen = new THREE.Color("#22C55E");
    const cGold = new THREE.Color("#FCD34D");
    const cWhite = new THREE.Color("#FFFFFF");

    for (let i = 0; i < actualCount; i++) {
      const rad = 0.15 + Math.random() * 0.75;
      const angle = Math.random() * Math.PI * 2;
      pos[i * 3] = 0.55 + Math.cos(angle) * rad;
      pos[i * 3 + 1] = -0.95 + Math.random() * 3.0;
      pos[i * 3 + 2] = Math.sin(angle) * rad;

      spd[i] = 0.015 + Math.random() * 0.04;

      const pick = Math.random();
      const chosen = pick > 0.85 ? cWhite : pick > 0.65 ? cGold : pick > 0.3 ? cNeon : cGreen;
      col[i * 3] = chosen.r;
      col[i * 3 + 1] = chosen.g;
      col[i * 3 + 2] = chosen.b;
    }
    return [pos, spd, col];
  }, [actualCount, low]);

  useFrame((_, delta) => {
    if (!pointsRef.current) return;
    const geo = pointsRef.current.geometry;
    const posAttr = geo.attributes.position;
    const mult = pumpActive ? 3.8 : 1.0;

    for (let i = 0; i < actualCount; i++) {
      let y = posAttr.getY(i) + speeds[i] * (delta * 60) * mult;
      if (y > 2.2) {
        y = -0.95 - Math.random() * 0.2;
      }
      posAttr.setY(i, y);
    }
    posAttr.needsUpdate = true;
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-color" args={[colors, 3]} />
      </bufferGeometry>
      <pointsMaterial
        size={low ? 0.04 : 0.028}
        vertexColors
        transparent
        opacity={0.9}
        sizeAttenuation
      />
    </points>
  );
}

// ---------------------------------------------------------------------------
// 3D HUD Badge (Shows live astronomical percentage ticker)
// ---------------------------------------------------------------------------
function FloatingHudBadge({ position, gainPct }) {
  const meshRef = useRef(null);

  const texture = useMemo(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 256;
    canvas.height = 120;
    const ctx = canvas.getContext("2d");

    // Sleek dark panel
    ctx.fillStyle = "rgba(10, 14, 23, 0.94)";
    ctx.beginPath();
    ctx.roundRect(4, 4, 248, 112, 10);
    ctx.fill();
    ctx.lineWidth = 3;
    ctx.strokeStyle = "#31E3AC";
    ctx.stroke();

    // Top ticker
    ctx.fillStyle = "#31E3AC";
    ctx.font = "900 32px monospace";
    ctx.fillText(`▲ +${gainPct}%`, 16, 44);

    // Subtitle
    ctx.fillStyle = "#F8FAFC";
    ctx.font = "bold 18px monospace";
    ctx.fillText("GOD CANDLE ATH", 16, 76);

    ctx.fillStyle = "#64748B";
    ctx.font = "13px monospace";
    ctx.fillText("VOL: 850,000 SOL", 16, 102);

    const tex = new THREE.CanvasTexture(canvas);
    tex.needsUpdate = true;
    return tex;
  }, [gainPct]);

  useFrame((state) => {
    if (!meshRef.current) return;
    meshRef.current.position.y = position[1] + Math.sin(state.clock.elapsedTime * 2) * 0.03;
  });

  return (
    <mesh ref={meshRef} position={position}>
      <planeGeometry args={[0.95, 0.45]} />
      <meshBasicMaterial map={texture} transparent opacity={0.95} side={THREE.DoubleSide} />
    </mesh>
  );
}

// ---------------------------------------------------------------------------
// The Monumental God Candle
// ---------------------------------------------------------------------------
function GodCandleBreakout({ pumpActive, onTriggerPump }) {
  const group = useRef(null);
  const candleMesh = useRef(null);
  const coreMesh = useRef(null);
  const shockRingRef = useRef(null);

  const [gain, setGain] = useState(8420);
  const currentHeight = useRef(1.85);
  const targetHeight = useRef(2.1);
  const { low } = usePerf();

  // Dynamic percentage counter
  useEffect(() => {
    const interval = setInterval(() => {
      setGain((g) => g + Math.floor(Math.random() * 85));
    }, 450);
    return () => clearInterval(interval);
  }, []);

  useFrame((state, delta) => {
    // Height oscillation or burst pump
    const baseTarget = pumpActive ? 2.65 : 2.15 + Math.sin(state.clock.elapsedTime * 2.5) * 0.12;
    targetHeight.current = baseTarget;

    // Smooth spring lerp
    currentHeight.current += (targetHeight.current - currentHeight.current) * 0.14;
    const h = currentHeight.current;

    // Scale main candle body
    if (candleMesh.current) {
      candleMesh.current.scale.set(1, h, 1);
      candleMesh.current.position.y = -0.42 + h / 2;
    }
    if (coreMesh.current) {
      coreMesh.current.scale.set(1, h * 0.98, 1);
      coreMesh.current.position.y = -0.42 + h / 2;
    }

    // Shockwave pulse
    if (shockRingRef.current) {
      if (pumpActive) {
        shockRingRef.current.scale.x += delta * 5.0;
        shockRingRef.current.scale.y += delta * 5.0;
        shockRingRef.current.material.opacity = Math.max(
          0,
          shockRingRef.current.material.opacity - delta * 1.8
        );
      } else {
        shockRingRef.current.scale.set(0.1, 0.1, 0.1);
        shockRingRef.current.material.opacity = 0.85;
      }
    }

    // Gentle camera parallax tracking
    if (group.current) {
      const targetY = state.pointer.x * 0.28;
      const targetX = state.pointer.y * 0.12;
      group.current.rotation.y += (targetY - group.current.rotation.y) * 0.08;
      group.current.rotation.x += (targetX - group.current.rotation.x) * 0.08;
    }

    if (low) state.invalidate();
  });

  const candleTopY = -0.42 + currentHeight.current;
  const candleX = 0.55;

  return (
    <group ref={group} onClick={onTriggerPump} cursor="pointer">
      {/* Historical Candlesticks establishing context and scale */}
      <HistoricalChart />

      {/* Chart Resistance Levels & Horizon Grid */}
      <ChartGridLines candleHeight={candleTopY} />

      {/* ================= GOD CANDLE STACK ================= */}
      <group position={[candleX, 0, 0]}>
        {/* Massive Volume Pillar (Breakout Liquidity) */}
        <mesh position={[0, -0.68, 0]}>
          <boxGeometry args={[0.34, 0.54, 0.24]} />
          <meshStandardMaterial
            color="#22C55E"
            emissive="#15803D"
            emissiveIntensity={0.6}
            roughness={0.2}
            metalness={0.3}
          />
        </mesh>

        {/* Lower Wick (Tail extending into the base) */}
        <mesh position={[0, -0.56, 0]}>
          <cylinderGeometry args={[0.018, 0.018, 0.28, 16]} />
          <meshStandardMaterial color="#22C55E" emissive="#15803D" emissiveIntensity={0.8} />
        </mesh>

        {/* Outer Crystal God Candle Body */}
        <mesh ref={candleMesh} position={[0, 0.5, 0]}>
          <boxGeometry args={[0.36, 1, 0.26]} />
          <meshPhysicalMaterial
            color="#00FFA3"
            emissive="#10B981"
            emissiveIntensity={pumpActive ? 0.95 : 0.65}
            roughness={0.12}
            metalness={0.15}
            transmission={0.65}
            thickness={0.6}
            ior={1.45}
            transparent
            opacity={0.92}
          />
        </mesh>

        {/* Inner Glowing Plasma Energy Filament */}
        <mesh ref={coreMesh} position={[0, 0.5, 0]}>
          <cylinderGeometry args={[0.045, 0.045, 1, 16]} />
          <meshBasicMaterial color="#ECFDF5" />
        </mesh>

        {/* Luminous Beveled Edge Highlights */}
        <mesh
          position={[0, -0.42 + currentHeight.current / 2, 0]}
          scale={[1.02, currentHeight.current, 1.02]}
        >
          <boxGeometry args={[0.36, 1, 0.26]} />
          <meshBasicMaterial color="#A7F3D0" wireframe transparent opacity={0.35} />
        </mesh>

        {/* Upper Wick Piercing The Stratosphere */}
        <mesh position={[0, candleTopY + 0.32, 0]}>
          <cylinderGeometry args={[0.018, 0.018, 0.64, 16]} />
          <meshStandardMaterial
            color="#A7F3D0"
            emissive="#31E3AC"
            emissiveIntensity={1.5}
          />
        </mesh>

        {/* Apex Flare Star Spark at the Peak */}
        <group position={[0, candleTopY + 0.64, 0]}>
          {/* Diamond Star */}
          <mesh rotation={[0, 0, Math.PI / 4]}>
            <octahedronGeometry args={[0.075, 0]} />
            <meshBasicMaterial color="#FFFFFF" />
          </mesh>
          {/* Corona Light Halo */}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.08, 0.22, 32]} />
            <meshBasicMaterial color="#31E3AC" transparent opacity={0.85} />
          </mesh>
        </group>

        {/* Breakthrough Shockwave Ring */}
        <mesh
          ref={shockRingRef}
          position={[0, candleTopY, 0]}
          rotation={[-Math.PI / 2, 0, 0]}
        >
          <ringGeometry args={[0.25, 0.32, 36]} />
          <meshBasicMaterial color="#31E3AC" transparent opacity={0.8} />
        </mesh>

        {/* Dedicated Point Light inside God Candle (Illuminates Chart) */}
        <pointLight
          position={[0, candleTopY * 0.6, 0.5]}
          intensity={pumpActive ? 4.5 : 2.8}
          color="#31E3AC"
          distance={4.5}
        />
      </group>

      {/* Floating 3D HUD Badge */}
      <FloatingHudBadge
        position={[candleX + 0.72, candleTopY - 0.1, 0.2]}
        gainPct={gain.toLocaleString()}
      />

      {/* Ascending Rocket Market Sparks */}
      <MarketSparkParticles pumpActive={pumpActive} count={low ? 40 : 130} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Root Scene
// ---------------------------------------------------------------------------
export default function IntakeScene({ onReady }) {
  const { low, post } = usePerf();
  const [pumpActive, setPumpActive] = useState(false);

  function triggerPump() {
    setPumpActive(true);
    setTimeout(() => setPumpActive(false), 950);
  }

  return (
    <Canvas
      dpr={low ? 1 : [1, 1.5]}
      frameloop={low ? "demand" : "always"}
      gl={{ antialias: !low, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [0, 0.4, 3.8], fov: 42 }}
      onCreated={({ gl, invalidate }) => {
        gl.setClearColor("#07090E", 1);
        onReady?.();
        invalidate();
      }}
    >
      <ambientLight intensity={0.6} />
      <directionalLight position={[4, 5, 4]} intensity={2.5} color="#FFFFFF" />
      <directionalLight position={[-4, 2, -1]} intensity={1.2} color="#059669" />

      <GodCandleBreakout pumpActive={pumpActive} onTriggerPump={triggerPump} />

      {post && (
        <EffectComposer disableNormalPass multisampling={0}>
          <Bloom
            intensity={0.65}
            luminanceThreshold={0.22}
            luminanceSmoothing={0.35}
            mipmapBlur
          />
        </EffectComposer>
      )}
    </Canvas>
  );
}

