// ---------------------------------------------------------------------------
// Main Animated Chart & God Candle Eruption with Camera Zoom-Out
// ---------------------------------------------------------------------------
function CinematicCandleChart({ onTriggerBreakout }) {
  const group = useRef(null);
  const candleMesh = useRef(null);
  const coreMesh = useRef(null);
  const shockRingRef = useRef(null);

  // Animation timeline state
  const animTime = useRef(0);
  const [visibleCandles, setVisibleCandles] = useState(0);
  const [godCandleActive, setGodCandleActive] = useState(false);
  const [gain, setGain] = useState(120);

  const currentHeight = useRef(0.04);
  const targetHeight = useRef(0.04);
  const { low } = usePerf();

  // Reset or manual trigger
  const CYCLE_DURATION = 13.5; // seconds per full loop

  useFrame((state, delta) => {
    animTime.current += delta;
    const t = animTime.current % CYCLE_DURATION;

    // 1. PHASE 1: Consolidation candles appear one-by-one (0s - 4.5s)
    if (t < 4.5) {
      const stepTime = 4.5 / CONSOLIDATION_SERIES.length;
      const count = Math.min(
        CONSOLIDATION_SERIES.length,
        Math.floor(t / stepTime) + 1
      );
      setVisibleCandles(count);
      setGodCandleActive(false);
      targetHeight.current = 0.04;
      setGain(Math.floor(80 + (t / 4.5) * 140));

      // Camera starts zoomed-in close, following the candle printing
      const currentCandleX = START_X + count * CANDLE_STEP;
      state.camera.position.x += (currentCandleX * 0.4 - state.camera.position.x) * 0.08;
      state.camera.position.y += (-0.25 - state.camera.position.y) * 0.08;
      state.camera.position.z += (2.4 - state.camera.position.z) * 0.08;
    }
    // 2. PHASE 2: GOD CANDLE BREAKOUT & CAMERA ZOOMS OUT (4.5s - 9.0s)
    else if (t >= 4.5 && t < 9.0) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setGodCandleActive(true);

      const pumpProgress = Math.min(1, (t - 4.5) / 2.8);
      // Ease out cubic
      const easedPump = 1 - Math.pow(1 - pumpProgress, 3);
      targetHeight.current = 0.04 + easedPump * 2.35;

      // Rocketing gain percentage
      setGain(Math.floor(220 + Math.pow(pumpProgress, 2.5) * 24200));

      // Camera CINEMATIC ZOOM-OUT: pulls back to reveal the entire monumental scale!
      state.camera.position.x += (0.1 - state.camera.position.x) * 0.06;
      state.camera.position.y += (0.42 - state.camera.position.y) * 0.06;
      state.camera.position.z += (4.6 - state.camera.position.z) * 0.06;
    }
    // 3. PHASE 3: ATH PEAK GLORY HOLD (9.0s - 13.0s)
    else {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setGodCandleActive(true);
      // Gentle breathing pulsation at peak
      targetHeight.current = 2.35 + Math.sin(t * 3) * 0.08;

      // Hold camera at wide angle
      state.camera.position.x += (0.1 - state.camera.position.x) * 0.05;
      state.camera.position.y += (0.42 - state.camera.position.y) * 0.05;
      state.camera.position.z += (4.6 - state.camera.position.z) * 0.05;
    }

    // Spring height lerp
    currentHeight.current += (targetHeight.current - currentHeight.current) * 0.14;
    const h = currentHeight.current;

    // Scale God Candle body
    if (candleMesh.current) {
      candleMesh.current.scale.set(1, Math.max(0.01, h), 1);
      candleMesh.current.position.y = -0.40 + h / 2;
    }
    if (coreMesh.current) {
      coreMesh.current.scale.set(1, Math.max(0.01, h * 0.98), 1);
      coreMesh.current.position.y = -0.40 + h / 2;
    }

    // Shockwave pulse
    if (shockRingRef.current) {
      if (godCandleActive && h > 0.8) {
        shockRingRef.current.scale.x += delta * 4.2;
        shockRingRef.current.scale.y += delta * 4.2;
        shockRingRef.current.material.opacity = Math.max(
          0,
          shockRingRef.current.material.opacity - delta * 1.4
        );
      } else {
        shockRingRef.current.scale.set(0.1, 0.1, 0.1);
        shockRingRef.current.material.opacity = 0.85;
      }
    }

    // Subtle parallax tilt from cursor
    if (group.current) {
      const targetTiltY = state.pointer.x * 0.22;
      const targetTiltX = state.pointer.y * 0.10;
      group.current.rotation.y += (targetTiltY - group.current.rotation.y) * 0.08;
      group.current.rotation.x += (targetTiltX - group.current.rotation.x) * 0.08;
    }

    if (low) state.invalidate();
  });

  const candleTopY = -0.40 + currentHeight.current;
  const godCandleX = START_X + CONSOLIDATION_SERIES.length * CANDLE_STEP + 0.12;

  function handleClick() {
    // Jump straight to eruption phase
    animTime.current = 4.6;
    onTriggerBreakout?.();
  }

  return (
    <group ref={group} onClick={handleClick} cursor="pointer">
      {/* Chart Grid Lines & Horizontal Resistance */}
      <ChartGridLines candleHeight={candleTopY} />

      {/* Consolidation Candlesticks appearing one-by-one */}
      <group>
        {CONSOLIDATION_SERIES.slice(0, visibleCandles).map((c, i) => {
          const posX = START_X + i * CANDLE_STEP;
          const bodyHeight = Math.max(0.04, Math.abs(c.close - c.open));
          const bodyY = (c.open + c.close) / 2;
          const wickHeight = Math.max(0.1, c.high - c.low);
          const wickY = (c.high + c.low) / 2;
          const color = c.green ? "#22C55E" : "#F43F5E";
          const emissive = c.green ? "#15803D" : "#BE123C";

          return (
            <group key={i} position={[posX, 0, 0]}>
              {/* Candle Body */}
              <mesh position={[0, bodyY, 0]}>
                <boxGeometry args={[0.105, bodyHeight, 0.09]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.35}
                  roughness={0.25}
                  metalness={0.2}
                />
              </mesh>

              {/* Wick */}
              <mesh position={[0, wickY, 0]}>
                <cylinderGeometry args={[0.007, 0.007, wickHeight, 8]} />
                <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={0.4} />
              </mesh>

              {/* Volume Bar */}
              <mesh position={[0, -0.85 + c.vol / 2, 0]}>
                <boxGeometry args={[0.105, c.vol, 0.09]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.25}
                  transparent
                  opacity={0.65}
                />
              </mesh>
            </group>
          );
        })}
      </group>

      {/* ================= THE TOWERING GOD CANDLE ================= */}
      {visibleCandles >= CONSOLIDATION_SERIES.length && (
        <group position={[godCandleX, 0, 0]}>
          {/* Astronomical Breakout Volume Bar */}
          <mesh position={[0, -0.58, 0]}>
            <boxGeometry args={[0.28, 0.54, 0.22]} />
            <meshStandardMaterial
              color="#22C55E"
              emissive="#15803D"
              emissiveIntensity={0.7}
              roughness={0.2}
              metalness={0.3}
            />
          </mesh>

          {/* Lower Wick */}
          <mesh position={[0, -0.52, 0]}>
            <cylinderGeometry args={[0.015, 0.015, 0.24, 16]} />
            <meshStandardMaterial color="#22C55E" emissive="#15803D" emissiveIntensity={0.8} />
          </mesh>

          {/* Translucent Emerald Crystal Body */}
          <mesh ref={candleMesh} position={[0, 0.5, 0]}>
            <boxGeometry args={[0.32, 1, 0.24]} />
            <meshPhysicalMaterial
              color="#00FFA3"
              emissive="#10B981"
              emissiveIntensity={godCandleActive ? 0.95 : 0.65}
              roughness={0.12}
              metalness={0.15}
              transmission={0.65}
              thickness={0.6}
              ior={1.45}
              transparent
              opacity={0.92}
            />
          </mesh>

          {/* Internal Radiant Plasma Energy Core */}
          <mesh ref={coreMesh} position={[0, 0.5, 0]}>
            <cylinderGeometry args={[0.04, 0.04, 1, 16]} />
            <meshBasicMaterial color="#ECFDF5" />
          </mesh>

          {/* Beveled Wireframe Highlight Edge */}
          <mesh
            position={[0, -0.40 + currentHeight.current / 2, 0]}
            scale={[1.02, Math.max(0.01, currentHeight.current), 1.02]}
          >
            <boxGeometry args={[0.32, 1, 0.24]} />
            <meshBasicMaterial color="#A7F3D0" wireframe transparent opacity={0.35} />
          </mesh>

          {/* Upper Wick Piercing the Heavens */}
          <mesh position={[0, candleTopY + 0.3, 0]}>
            <cylinderGeometry args={[0.015, 0.015, 0.6, 16]} />
            <meshStandardMaterial
              color="#A7F3D0"
              emissive="#31E3AC"
              emissiveIntensity={1.5}
            />
          </mesh>

          {/* Apex Plasma Flare Diamond Star */}
          <group position={[0, candleTopY + 0.6, 0]}>
            <mesh rotation={[0, 0, Math.PI / 4]}>
              <octahedronGeometry args={[0.07, 0]} />
              <meshBasicMaterial color="#FFFFFF" />
            </mesh>
            <mesh rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[0.08, 0.20, 32]} />
              <meshBasicMaterial color="#31E3AC" transparent opacity={0.85} />
            </mesh>
          </group>

          {/* Breakthrough Shockwave Ring */}
          <mesh
            ref={shockRingRef}
            position={[0, candleTopY, 0]}
            rotation={[-Math.PI / 2, 0, 0]}
          >
            <ringGeometry args={[0.22, 0.28, 36]} />
            <meshBasicMaterial color="#31E3AC" transparent opacity={0.8} />
          </mesh>

          {/* Point Light Casting Emerald Radiance */}
          <pointLight
            position={[0, candleTopY * 0.6, 0.4]}
            intensity={godCandleActive ? 4.2 : 1.8}
            color="#31E3AC"
            distance={5.0}
          />
        </group>
      )}

      {/* Floating 3D HUD Percentage Badge */}
      <FloatingHudBadge
        position={[godCandleX + 0.72, candleTopY - 0.1, 0.2]}
        gainPct={gain.toLocaleString()}
        isVisible={godCandleActive}
      />

      {/* Upward Rising Rocket Market Sparks */}
      <MarketSparkParticles count={low ? 40 : 130} godCandleActive={godCandleActive} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Root Scene
// ---------------------------------------------------------------------------
export default function IntakeScene({ onReady }) {
  const { low, post } = usePerf();

  return (
    <Canvas
      dpr={low ? 1 : [1, 1.5]}
      frameloop={low ? "demand" : "always"}
      gl={{ antialias: !low, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [START_X, -0.15, 2.4], fov: 44 }}
      onCreated={({ gl, invalidate }) => {
        gl.setClearColor("#07090E", 1);
        onReady?.();
        invalidate();
      }}
    >
      <ambientLight intensity={0.65} />
      <directionalLight position={[4, 5, 4]} intensity={2.6} color="#FFFFFF" />
      <directionalLight position={[-4, 2, -1]} intensity={1.2} color="#059669" />

      <CinematicCandleChart />

      {post && (
        <EffectComposer disableNormalPass multisampling={0}>
          <Bloom
            intensity={0.65}
            luminanceThreshold={0.22}
            luminanceSmoothing={0.35}
            mipmapBlur
          />
        </EffectComposer>
      )}
    </Canvas>
  );
}

