      state.camera.position.z += (2.4 - state.camera.position.z) * 0.08;
    }
    // 2. PHASE 2: GOD CANDLE BREAKOUT & CAMERA ZOOMS OUT (4.5s - 9.0s)
    else if (t >= 4.5 && t < 9.0) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setGodCandleActive(true);

      const pumpProgress = Math.min(1, (t - 4.5) / 2.8);
      // Ease out cubic
      const easedPump = 1 - Math.pow(1 - pumpProgress, 3);
      targetHeight.current = 0.04 + easedPump * 2.35;

      // Rocketing gain percentage
      setGain(Math.floor(220 + Math.pow(pumpProgress, 2.5) * 24200));

      // Camera CINEMATIC ZOOM-OUT: pulls back to reveal the entire monumental scale!
      state.camera.position.x += (0.1 - state.camera.position.x) * 0.06;
      state.camera.position.y += (0.42 - state.camera.position.y) * 0.06;
      state.camera.position.z += (4.6 - state.camera.position.z) * 0.06;
    }
    // 3. PHASE 3: ATH PEAK GLORY HOLD (9.0s - 13.0s)
    else {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setGodCandleActive(true);
      // Gentle breathing pulsation at peak
      targetHeight.current = 2.35 + Math.sin(t * 3) * 0.08;

      // Hold camera at wide angle
      state.camera.position.x += (0.1 - state.camera.position.x) * 0.05;
      state.camera.position.y += (0.42 - state.camera.position.y) * 0.05;
      state.camera.position.z += (4.6 - state.camera.position.z) * 0.05;
    }

    // Spring height lerp
    currentHeight.current += (targetHeight.current - currentHeight.current) * 0.14;
    const h = currentHeight.current;

    // Scale God Candle body
    if (candleMesh.current) {
      candleMesh.current.scale.set(1, Math.max(0.01, h), 1);
      candleMesh.current.position.y = -0.40 + h / 2;
    }
    if (coreMesh.current) {
      coreMesh.current.scale.set(1, Math.max(0.01, h * 0.98), 1);
      coreMesh.current.position.y = -0.40 + h / 2;
    }

    // Shockwave pulse
    if (shockRingRef.current) {
      if (godCandleActive && h > 0.8) {
        shockRingRef.current.scale.x += delta * 4.2;
        shockRingRef.current.scale.y += delta * 4.2;
        shockRingRef.current.material.opacity = Math.max(
          0,
          shockRingRef.current.material.opacity - delta * 1.4
        );
      } else {
        shockRingRef.current.scale.set(0.1, 0.1, 0.1);
        shockRingRef.current.material.opacity = 0.85;
      }
    }

    // Subtle parallax tilt from cursor
    if (group.current) {
      const targetTiltY = state.pointer.x * 0.22;
      const targetTiltX = state.pointer.y * 0.10;
      group.current.rotation.y += (targetTiltY - group.current.rotation.y) * 0.08;
      group.current.rotation.x += (targetTiltX - group.current.rotation.x) * 0.08;
    }

    if (low) state.invalidate();
  });

  const candleTopY = -0.40 + currentHeight.current;
  const godCandleX = START_X + CONSOLIDATION_SERIES.length * CANDLE_STEP + 0.12;

  function handleClick() {
    // Jump straight to eruption phase
    animTime.current = 4.6;
    onTriggerBreakout?.();
  }

  return (
    <group ref={group} onClick={handleClick} cursor="pointer">
      {/* Chart Grid Lines & Horizontal Resistance */}
      <ChartGridLines candleHeight={candleTopY} />

      {/* Consolidation Candlesticks appearing one-by-one */}
      <group>
        {CONSOLIDATION_SERIES.slice(0, visibleCandles).map((c, i) => {
          const posX = START_X + i * CANDLE_STEP;
          const bodyHeight = Math.max(0.04, Math.abs(c.close - c.open));
          const bodyY = (c.open + c.close) / 2;
          const wickHeight = Math.max(0.1, c.high - c.low);
          const wickY = (c.high + c.low) / 2;
          const color = c.green ? "#22C55E" : "#F43F5E";
          const emissive = c.green ? "#15803D" : "#BE123C";

          return (
            <group key={i} position={[posX, 0, 0]}>
              {/* Candle Body */}
              <mesh position={[0, bodyY, 0]}>
                <boxGeometry args={[0.105, bodyHeight, 0.09]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.35}
                  roughness={0.25}
                  metalness={0.2}
                />
              </mesh>

              {/* Wick */}
              <mesh position={[0, wickY, 0]}>
                <cylinderGeometry args={[0.007, 0.007, wickHeight, 8]} />
                <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={0.4} />
              </mesh>

              {/* Volume Bar */}
              <mesh position={[0, -0.85 + c.vol / 2, 0]}>
                <boxGeometry args={[0.105, c.vol, 0.09]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.25}
                  transparent
                  opacity={0.65}
                />
              </mesh>
            </group>
          );
        })}
      </group>

      {/* ================= THE TOWERING GOD CANDLE ================= */}
      {visibleCandles >= CONSOLIDATION_SERIES.length && (
        <group position={[godCandleX, 0, 0]}>
          {/* Astronomical Breakout Volume Bar */}
          <mesh position={[0, -0.58, 0]}>
            <boxGeometry args={[0.28, 0.54, 0.22]} />
            <meshStandardMaterial
              color="#22C55E"
              emissive="#15803D"
              emissiveIntensity={0.7}
              roughness={0.2}
              metalness={0.3}
            />
          </mesh>

          {/* Lower Wick */}
          <mesh position={[0, -0.52, 0]}>
            <cylinderGeometry args={[0.015, 0.015, 0.24, 16]} />
            <meshStandardMaterial color="#22C55E" emissive="#15803D" emissiveIntensity={0.8} />
          </mesh>

          {/* Translucent Emerald Crystal Body */}
          <mesh ref={candleMesh} position={[0, 0.5, 0]}>
            <boxGeometry args={[0.32, 1, 0.24]} />
            <meshPhysicalMaterial
              color="#00FFA3"
              emissive="#10B981"
              emissiveIntensity={godCandleActive ? 0.95 : 0.65}
              roughness={0.12}
              metalness={0.15}
              transmission={0.65}
              thickness={0.6}
              ior={1.45}
              transparent
              opacity={0.92}
            />
          </mesh>

          {/* Internal Radiant Plasma Energy Core */}
          <mesh ref={coreMesh} position={[0, 0.5, 0]}>
            <cylinderGeometry args={[0.04, 0.04, 1, 16]} />
            <meshBasicMaterial color="#ECFDF5" />
          </mesh>

          {/* Beveled Wireframe Highlight Edge */}
          <mesh
            position={[0, -0.40 + currentHeight.current / 2, 0]}
            scale={[1.02, Math.max(0.01, currentHeight.current), 1.02]}
          >
            <boxGeometry args={[0.32, 1, 0.24]} />
            <meshBasicMaterial color="#A7F3D0" wireframe transparent opacity={0.35} />
          </mesh>

          {/* Upper Wick Piercing the Heavens */}
          <mesh position={[0, candleTopY + 0.3, 0]}>
            <cylinderGeometry args={[0.015, 0.015, 0.6, 16]} />
            <meshStandardMaterial
              color="#A7F3D0"
              emissive="#31E3AC"
              emissiveIntensity={1.5}
            />
          </mesh>

          {/* Apex Plasma Flare Diamond Star */}
          <group position={[0, candleTopY + 0.6, 0]}>
            <mesh rotation={[0, 0, Math.PI / 4]}>
              <octahedronGeometry args={[0.07, 0]} />
              <meshBasicMaterial color="#FFFFFF" />
            </mesh>
            <mesh rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[0.08, 0.20, 32]} />
              <meshBasicMaterial color="#31E3AC" transparent opacity={0.85} />
            </mesh>
          </group>

          {/* Breakthrough Shockwave Ring */}
          <mesh
            ref={shockRingRef}
            position={[0, candleTopY, 0]}
            rotation={[-Math.PI / 2, 0, 0]}
          >
            <ringGeometry args={[0.22, 0.28, 36]} />
            <meshBasicMaterial color="#31E3AC" transparent opacity={0.8} />
          </mesh>

          {/* Point Light Casting Emerald Radiance */}
          <pointLight
            position={[0, candleTopY * 0.6, 0.4]}
            intensity={godCandleActive ? 4.2 : 1.8}
            color="#31E3AC"
            distance={5.0}
          />
        </group>
      )}

      {/* Floating 3D HUD Percentage Badge */}
      <FloatingHudBadge
        position={[godCandleX + 0.72, candleTopY - 0.1, 0.2]}
        gainPct={gain.toLocaleString()}
        isVisible={godCandleActive}
      />

      {/* Upward Rising Rocket Market Sparks */}
      <MarketSparkParticles count={low ? 40 : 130} godCandleActive={godCandleActive} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Root Scene
// ---------------------------------------------------------------------------
export default function IntakeScene({ onReady }) {
  const { low, post } = usePerf();

  return (
    <Canvas
      dpr={low ? 1 : [1, 1.5]}
      frameloop={low ? "demand" : "always"}
      gl={{ antialias: !low, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [START_X, -0.15, 2.4], fov: 44 }}
      onCreated={({ gl, invalidate }) => {
        gl.setClearColor("#07090E", 1);
        onReady?.();
        invalidate();
      }}
    >
      <ambientLight intensity={0.65} />
      <directionalLight position={[4, 5, 4]} intensity={2.6} color="#FFFFFF" />
      <directionalLight position={[-4, 2, -1]} intensity={1.2} color="#059669" />

      <CinematicCandleChart />

      {post && (
        <EffectComposer disableNormalPass multisampling={0}>
          <Bloom
            intensity={0.65}
            luminanceThreshold={0.22}
            luminanceSmoothing={0.35}
            mipmapBlur
          />
        </EffectComposer>
      )}
    </Canvas>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { EffectComposer, Bloom } from "@react-three/postprocessing";
import * as THREE from "three";
import { usePerf } from "../perf/PerfProvider.jsx";

// ---------------------------------------------------------------------------
// 10 Consolidation Candlesticks (Sequence that prints rapidly at baseline)
// ---------------------------------------------------------------------------
const CONSOLIDATION_SERIES = [
  { open: -1.05, close: -1.14, high: -1.00, low: -1.18, green: false, vol: 0.12 },
  { open: -1.14, close: -1.06, high: -1.03, low: -1.16, green: true,  vol: 0.15 },
  { open: -1.06, close: -1.12, high: -1.04, low: -1.15, green: false, vol: 0.10 },
  { open: -1.12, close: -1.02, high: -0.98, low: -1.15, green: true,  vol: 0.18 },
  { open: -1.02, close: -1.08, high: -0.99, low: -1.11, green: false, vol: 0.14 },
  { open: -1.08, close: -1.01, high: -0.96, low: -1.10, green: true,  vol: 0.20 },
  { open: -1.01, close: -1.06, high: -0.98, low: -1.09, green: false, vol: 0.13 },
  { open: -1.06, close: -0.97, high: -0.93, low: -1.08, green: true,  vol: 0.24 },
  { open: -0.97, close: -1.02, high: -0.94, low: -1.05, green: false, vol: 0.16 },
  { open: -1.02, close: -0.94, high: -0.90, low: -1.04, green: true,  vol: 0.28 },
];

const CANDLE_STEP = 0.22;
const START_X = -2.2;
const BASELINE_Y = -1.02;

// ---------------------------------------------------------------------------
// Chart Grid & Stratospheric Resistance Levels
// ---------------------------------------------------------------------------
function ChartGridLines({ candleHeight }) {
  const levels = [
    { y: -1.35, label: "GROUND SUPPORT ($0.01)", color: "#334155" },
    { y: -0.95, label: "CONSOLIDATION BASE ($0.10)", color: "#475569" },
    { y: 0.20,  label: "RESISTANCE 1 ($1.00) [SHATTERED]", color: "#059669" },
    { y: 1.40,  label: "RESISTANCE 2 ($10.0) [SHATTERED]", color: "#10B981" },
    { y: 2.60,  label: "STRATOSPHERE ATH ($100.0) [BROKEN]", color: "#31E3AC" },
    { y: 3.60,  label: "ORBITAL ESCAPE ($1000.0+)", color: "#86EFAC" },
  ];

  return (
    <group position={[0, 0, -0.2]}>
      {levels.map((lvl, idx) => {
        const breached = candleHeight > lvl.y;
        return (
          <group key={idx} position={[0, lvl.y, 0]}>
            <mesh>
              <boxGeometry args={[7.2, 0.012, 0.012]} />
              <meshBasicMaterial
                color={breached ? lvl.color : "#1E293B"}
                transparent
                opacity={breached ? 0.85 : 0.25}
              />
            </mesh>
          </group>
        );
      })}

      {/* Deep Ground Grid */}
      <mesh position={[0, -1.38, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[7.4, 3.2]} />
        <meshBasicMaterial color="#06080D" />
      </mesh>
      <gridHelper args={[7.4, 22, "#1E293B", "#0D131F"]} position={[0, -1.375, 0]} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Ascending Rocket Fuel Sparks
// ---------------------------------------------------------------------------
function MarketSparkParticles({ count = 160, erupting }) {
  const pointsRef = useRef(null);
  const { low } = usePerf();
  const actualCount = low ? 45 : count;

  const [positions, speeds, colors] = useMemo(() => {
    const pos = new Float32Array(actualCount * 3);
    const spd = new Float32Array(actualCount);
    const col = new Float32Array(actualCount * 3);

    const cNeon = new THREE.Color("#31E3AC");
    const cGreen = new THREE.Color("#22C55E");
    const cGold = new THREE.Color("#FCD34D");
    const cWhite = new THREE.Color("#FFFFFF");

    for (let i = 0; i < actualCount; i++) {
      const rad = 0.2 + Math.random() * 1.1;
      const angle = Math.random() * Math.PI * 2;
      pos[i * 3] = 0.5 + Math.cos(angle) * rad;
      pos[i * 3 + 1] = -1.4 + Math.random() * 5.2;
      pos[i * 3 + 2] = Math.sin(angle) * rad;

      spd[i] = 0.02 + Math.random() * 0.06;

      const pick = Math.random();
      const chosen = pick > 0.8 ? cWhite : pick > 0.6 ? cGold : pick > 0.25 ? cNeon : cGreen;
      col[i * 3] = chosen.r;
      col[i * 3 + 1] = chosen.g;
      col[i * 3 + 2] = chosen.b;
    }
    return [pos, spd, col];
  }, [actualCount, low]);

  useFrame((_, delta) => {
    if (!pointsRef.current) return;
    const geo = pointsRef.current.geometry;
    const posAttr = geo.attributes.position;
    const mult = erupting ? 4.2 : 1.2;

    for (let i = 0; i < actualCount; i++) {
      let y = posAttr.getY(i) + speeds[i] * (delta * 60) * mult;
      if (y > 4.2) {
        y = -1.4 - Math.random() * 0.3;
      }
      posAttr.setY(i, y);
    }
    posAttr.needsUpdate = true;
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-color" args={[colors, 3]} />
      </bufferGeometry>
      <pointsMaterial
        size={low ? 0.05 : 0.038}
        vertexColors
        transparent
        opacity={erupting ? 0.95 : 0.55}
        sizeAttenuation
      />
    </points>
  );
}

// ---------------------------------------------------------------------------
// 3D Floating HUD Banner
// ---------------------------------------------------------------------------
function FloatingHudBadge({ position, gainPct, isVisible }) {
  const meshRef = useRef(null);

  const texture = useMemo(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 256;
    canvas.height = 120;
    const ctx = canvas.getContext("2d");

    ctx.fillStyle = "rgba(7, 10, 16, 0.95)";
    ctx.beginPath();
    ctx.roundRect(4, 4, 248, 112, 10);
    ctx.fill();
    ctx.lineWidth = 3.5;
    ctx.strokeStyle = "#31E3AC";
    ctx.stroke();

    ctx.fillStyle = "#31E3AC";
    ctx.font = "900 34px monospace";
    ctx.fillText(`▲ +${gainPct}%`, 16, 44);

    ctx.fillStyle = "#F8FAFC";
    ctx.font = "bold 18px monospace";
    ctx.fillText("GOD CANDLE ATH", 16, 76);

    ctx.fillStyle = "#64748B";
    ctx.font = "bold 13px monospace";
    ctx.fillText("VOLUME: $148,000,000", 16, 102);

    const tex = new THREE.CanvasTexture(canvas);
    tex.needsUpdate = true;
    return tex;
  }, [gainPct]);

  useFrame((state) => {
    if (!meshRef.current) return;
    meshRef.current.position.y = position[1] + Math.sin(state.clock.elapsedTime * 2.2) * 0.04;
    meshRef.current.scale.setScalar(isVisible ? 1 : 0);
  });

  return (
    <mesh ref={meshRef} position={position}>
      <planeGeometry args={[1.15, 0.55]} />
      <meshBasicMaterial map={texture} transparent opacity={0.96} side={THREE.DoubleSide} />
    </mesh>
  );
}

// ---------------------------------------------------------------------------
// Main Cinematic God Candle Chart
// ---------------------------------------------------------------------------
function CinematicGodCandle() {
  const group = useRef(null);
  const candleMesh = useRef(null);
  const coreMesh = useRef(null);
  const shockRingRef = useRef(null);

  // Growth animation timing
  const animTime = useRef(0);
  const [visibleCandles, setVisibleCandles] = useState(0);
  const [erupting, setErupting] = useState(false);
  const [gain, setGain] = useState(140);

  const currentHeight = useRef(0.08);
  const targetHeight = useRef(0.08);

  const CYCLE_DURATION = 12.0; // 12 second loop

  useFrame((state, delta) => {
    animTime.current += delta;
    const t = animTime.current % CYCLE_DURATION;

    // Phase 1: Rapid printing of 10 consolidation candles (0s - 1.8s)
    if (t < 1.8) {
      const stepTime = 1.8 / CONSOLIDATION_SERIES.length;
      const count = Math.min(
        CONSOLIDATION_SERIES.length,
        Math.floor(t / stepTime) + 1
      );
      setVisibleCandles(count);
      setErupting(false);
      targetHeight.current = 0.08;
      setGain(Math.floor(100 + (t / 1.8) * 180));

      // Camera starts closer at baseline to show the tight accumulation
      const curX = START_X + count * CANDLE_STEP;
      state.camera.position.x += (curX * 0.45 - state.camera.position.x) * 0.1;
      state.camera.position.y += (-0.6 - state.camera.position.y) * 0.1;
      state.camera.position.z += (3.2 - state.camera.position.z) * 0.1;
    }
    // Phase 2: GOD CANDLE EXPLOSIVE GROWTH & CAMERA ZOOMS OUT (1.8s - 6.5s)
    else if (t >= 1.8 && t < 6.5) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setErupting(true);

      const pumpProgress = Math.min(1, (t - 1.8) / 3.4);
      // Aggressive explosive cubic power growth
      const pumpCurve = 1 - Math.pow(1 - pumpProgress, 3.5);

      // SHOOTS FROM 0.08 UP TO 4.6 UNITS TALL! (Gigantic towering monolith)
      targetHeight.current = 0.08 + pumpCurve * 4.52;

      // Exponential percentage ticker (+48,000%!)
      setGain(Math.floor(280 + Math.pow(pumpProgress, 2.8) * 48200));

      // Camera ZOOMS OUT and elevates upward to capture the full monumental titan
      state.camera.position.x += (0.15 - state.camera.position.x) * 0.06;
      state.camera.position.y += (0.85 - state.camera.position.y) * 0.06;
      state.camera.position.z += (5.6 - state.camera.position.z) * 0.06;
    }
    // Phase 3: ATH Stratosphere Hold & Breathing Pulsation (6.5s - 11.5s)
    else if (t >= 6.5 && t < 11.5) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setErupting(true);
      // Pulsing power at apex
      targetHeight.current = 4.60 + Math.sin(t * 3.2) * 0.15;

      // Full wide camera view
      state.camera.position.x += (0.15 - state.camera.position.x) * 0.05;
      state.camera.position.y += (0.85 - state.camera.position.y) * 0.05;
      state.camera.position.z += (5.6 - state.camera.position.z) * 0.05;
    }
    // Phase 4: Loop reset transition (11.5s - 12.0s)
    else {
      // Fade into next cycle
      targetHeight.current = 0.08;
    }

    // Fast responsive lerp for visceral growth
    currentHeight.current += (targetHeight.current - currentHeight.current) * 0.16;
    const h = Math.max(0.04, currentHeight.current);

    // Update main God Candle body scale and anchor base at BASELINE_Y
    if (candleMesh.current) {
      candleMesh.current.scale.set(1, h, 1);
      candleMesh.current.position.y = BASELINE_Y + h / 2;
    }
    if (coreMesh.current) {
      coreMesh.current.scale.set(1, h * 0.98, 1);
      coreMesh.current.position.y = BASELINE_Y + h / 2;
    }

    // Expanding shockwave pulse at current apex
    if (shockRingRef.current) {
      if (erupting && h > 1.2) {
        shockRingRef.current.scale.x += delta * 5.0;
        shockRingRef.current.scale.y += delta * 5.0;
        shockRingRef.current.material.opacity = Math.max(
          0,
          shockRingRef.current.material.opacity - delta * 1.6
        );
      } else {
        shockRingRef.current.scale.set(0.1, 0.1, 0.1);
        shockRingRef.current.material.opacity = 0.9;
      }
    }

    // Interactive mouse tilt parallax
    if (group.current) {
      const targetTiltY = state.pointer.x * 0.24;
      const targetTiltX = state.pointer.y * 0.10;
      group.current.rotation.y += (targetTiltY - group.current.rotation.y) * 0.08;
      group.current.rotation.x += (targetTiltX - group.current.rotation.x) * 0.08;
    }
  });

  const candleTopY = BASELINE_Y + currentHeight.current;
  const godCandleX = START_X + CONSOLIDATION_SERIES.length * CANDLE_STEP + 0.18;

  function triggerExplosion() {
    // Jump straight to rocket eruption
    animTime.current = 1.85;
  }

  return (
    <group ref={group} onClick={triggerExplosion} cursor="pointer">
      {/* Chart Grid Lines & Horizontal Resistance */}
      <ChartGridLines candleHeight={candleTopY} />

      {/* Preceding Historical Consolidation Candlesticks */}
      <group>
        {CONSOLIDATION_SERIES.slice(0, visibleCandles).map((c, i) => {
          const posX = START_X + i * CANDLE_STEP;
          const bodyHeight = Math.max(0.05, Math.abs(c.close - c.open));
          const bodyY = (c.open + c.close) / 2;
          const wickHeight = Math.max(0.12, c.high - c.low);
          const wickY = (c.high + c.low) / 2;
          const color = c.green ? "#22C55E" : "#F43F5E";
          const emissive = c.green ? "#15803D" : "#BE123C";

          return (
            <group key={i} position={[posX, 0, 0]}>
              {/* Body */}
              <mesh position={[0, bodyY, 0]}>
                <boxGeometry args={[0.15, bodyHeight, 0.12]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.35}
                  roughness={0.25}
                  metalness={0.2}
                />
              </mesh>

              {/* Wick */}
              <mesh position={[0, wickY, 0]}>
                <cylinderGeometry args={[0.009, 0.009, wickHeight, 8]} />
                <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={0.4} />
              </mesh>

              {/* Volume Bar */}
              <mesh position={[0, -1.35 + c.vol / 2, 0]}>
                <boxGeometry args={[0.15, c.vol, 0.12]} />
