// ---------------------------------------------------------------------------
// 10 Consolidation Candlesticks (Accumulation chop leading into God Candle)
// Positioned safely on the left: from x = -2.55 to x = -0.85
// Spacing = 0.17 -> all 10 candles fit within ~1.7 units on the left
// The God Candle sits prominently centered at x = 0.0 with width = 1.30
// ---------------------------------------------------------------------------
const CONSOLIDATION_SERIES = [
  { open: -0.98, close: -1.06, high: -0.94, low: -1.10, green: false, vol: 0.14 },
  { open: -1.06, close: -0.99, high: -0.96, low: -1.08, green: true,  vol: 0.18 },
  { open: -0.99, close: -1.04, high: -0.97, low: -1.07, green: false, vol: 0.12 },
  { open: -1.04, close: -0.96, high: -0.92, low: -1.07, green: true,  vol: 0.22 },
  { open: -0.96, close: -1.01, high: -0.93, low: -1.04, green: false, vol: 0.16 },
  { open: -1.01, close: -0.94, high: -0.90, low: -1.03, green: true,  vol: 0.25 },
  { open: -0.94, close: -0.99, high: -0.91, low: -1.02, green: false, vol: 0.15 },
  { open: -0.99, close: -0.91, high: -0.87, low: -1.01, green: true,  vol: 0.28 },
  { open: -0.91, close: -0.95, high: -0.88, low: -0.98, green: false, vol: 0.19 },
  { open: -0.95, close: -0.88, high: -0.84, low: -0.97, green: true,  vol: 0.32 },
];

const CONSOLIDATION_START_X = -2.55;
const CONSOLIDATION_STEP = 0.18;
const BASELINE_Y = -0.92;
const GOD_CANDLE_X = 0.0; // PURE CENTER HORIZONTALLY
const GOD_CANDLE_WIDTH = 1.30; // MASSIVE, MONUMENTAL WIDTH
const GOD_CANDLE_DEPTH = 0.78; // VOLUMETRIC MONOLITH DEPTH

// ---------------------------------------------------------------------------
// Chart Grid & Stratospheric Resistance Levels
// Spans widely across the entire screen so it frames both sides evenly
// ---------------------------------------------------------------------------
function ChartGridLines({ candleHeight }) {
  const levels = [
    { y: -1.30, label: "GROUND ACCUMULATION ($0.01)", color: "#334155" },
    { y: -0.88, label: "BREAKOUT BASE ($0.10)", color: "#475569" },
    { y: 0.35,  label: "RESISTANCE 1 ($1.00) [SHATTERED]", color: "#059669" },
    { y: 1.65,  label: "RESISTANCE 2 ($10.0) [SHATTERED]", color: "#10B981" },
    { y: 2.95,  label: "STRATOSPHERE ATH ($100.0) [BROKEN]", color: "#31E3AC" },
    { y: 4.10,  label: "ORBITAL ESCAPE ($1000.0+)", color: "#86EFAC" },
  ];

  return (
    <group position={[0, 0, -0.2]}>
      {levels.map((lvl, idx) => {
        const breached = candleHeight > lvl.y;
        return (
          <group key={idx} position={[0, lvl.y, 0]}>
            <mesh>
              <boxGeometry args={[11.5, 0.015, 0.015]} />
              <meshBasicMaterial
                color={breached ? lvl.color : "#1E293B"}
                transparent
                opacity={breached ? 0.9 : 0.22}
              />
            </mesh>
          </group>
        );
      })}

      {/* Deep Ground Grid Base */}
      <mesh position={[0, -1.34, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[12.0, 4.0]} />
        <meshBasicMaterial color="#05070B" />
      </mesh>
      <gridHelper args={[12.0, 32, "#1E293B", "#0B101B"]} position={[0, -1.335, 0]} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Ascending Rocket Fuel Sparks
// ---------------------------------------------------------------------------
function MarketSparkParticles({ count = 180, erupting }) {
  const pointsRef = useRef(null);
  const { low } = usePerf();
  const actualCount = low ? 50 : count;

  const [positions, speeds, colors] = useMemo(() => {
    const pos = new Float32Array(actualCount * 3);
    const spd = new Float32Array(actualCount);
    const col = new Float32Array(actualCount * 3);

    const cNeon = new THREE.Color("#31E3AC");
    const cGreen = new THREE.Color("#22C55E");
    const cGold = new THREE.Color("#FCD34D");
    const cWhite = new THREE.Color("#FFFFFF");

    for (let i = 0; i < actualCount; i++) {
      // Concentrate sparks symmetrically around the center God Candle
      const radX = (Math.random() - 0.5) * 3.2;
      const radZ = (Math.random() - 0.5) * 1.6;
      pos[i * 3] = radX;
      pos[i * 3 + 1] = -1.4 + Math.random() * 5.6;
      pos[i * 3 + 2] = radZ;

      spd[i] = 0.025 + Math.random() * 0.07;

      const pick = Math.random();
      const chosen = pick > 0.8 ? cWhite : pick > 0.6 ? cGold : pick > 0.25 ? cNeon : cGreen;
      col[i * 3] = chosen.r;
      col[i * 3 + 1] = chosen.g;
      col[i * 3 + 2] = chosen.b;
    }
    return [pos, spd, col];
  }, [actualCount, low]);

  useFrame((_, delta) => {
    if (!pointsRef.current) return;
    const geo = pointsRef.current.geometry;
    const posAttr = geo.attributes.position;
    const mult = erupting ? 4.5 : 1.2;

    for (let i = 0; i < actualCount; i++) {
      let y = posAttr.getY(i) + speeds[i] * (delta * 60) * mult;
      if (y > 4.6) {
        y = -1.4 - Math.random() * 0.3;
      }
      posAttr.setY(i, y);
    }
    posAttr.needsUpdate = true;
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-color" args={[colors, 3]} />
      </bufferGeometry>
      <pointsMaterial
        size={low ? 0.05 : 0.042}
        vertexColors
        transparent
        opacity={erupting ? 0.95 : 0.55}
        sizeAttenuation
      />
    </points>
  );
}

// ---------------------------------------------------------------------------
// 3D Floating HUD Banner (Docked smoothly on the right side of God Candle)
// ---------------------------------------------------------------------------
function FloatingHudBadge({ position, gainPct, isVisible }) {
  const meshRef = useRef(null);

  const texture = useMemo(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 300;
    canvas.height = 140;
    const ctx = canvas.getContext("2d");

    // Dark glass background
    ctx.fillStyle = "rgba(7, 10, 16, 0.96)";
    ctx.beginPath();
    ctx.roundRect(4, 4, 292, 132, 12);
    ctx.fill();

    // Glowing border
    ctx.lineWidth = 4;
    ctx.strokeStyle = "#31E3AC";
    ctx.stroke();

    // Percentage Gain
    ctx.fillStyle = "#31E3AC";
    ctx.font = "900 40px monospace";
    ctx.fillText(`▲ +${gainPct}%`, 18, 50);

    // Subtitle
    ctx.fillStyle = "#F8FAFC";
    ctx.font = "bold 20px monospace";
    ctx.fillText("GOD CANDLE ATH", 18, 88);

    // Sol Volume
    ctx.fillStyle = "#94A3B8";
    ctx.font = "bold 15px monospace";
    ctx.fillText("VOL: 2,450,000 SOL", 18, 118);

    const tex = new THREE.CanvasTexture(canvas);
    tex.needsUpdate = true;
    return tex;
  }, [gainPct]);

  useFrame((state) => {
    if (!meshRef.current) return;
    meshRef.current.position.y = position[1] + Math.sin(state.clock.elapsedTime * 2.2) * 0.05;
    meshRef.current.scale.setScalar(isVisible ? 1 : 0);
  });

  return (
    <mesh ref={meshRef} position={position}>
      <planeGeometry args={[1.45, 0.68]} />
      <meshBasicMaterial map={texture} transparent opacity={0.98} side={THREE.DoubleSide} />
    </mesh>
  );
}

// ---------------------------------------------------------------------------
// Main Cinematic God Candle Stage
// ---------------------------------------------------------------------------
function CinematicGodCandle() {
  const group = useRef(null);
  const candleMesh = useRef(null);
  const coreMesh = useRef(null);
  const wireFrameMesh = useRef(null);
  const shockRingRef = useRef(null);

  // Growth animation timing
  const animTime = useRef(0);
  const [visibleCandles, setVisibleCandles] = useState(0);
  const [erupting, setErupting] = useState(false);
  const [gain, setGain] = useState(140);

  const currentHeight = useRef(0.12);
  const targetHeight = useRef(0.12);

  const CYCLE_DURATION = 12.0;

  useFrame((state, delta) => {
    animTime.current += delta;
    const t = animTime.current % CYCLE_DURATION;

    let targetCamY = 0.0;
    let targetCamZ = 4.8;
    let targetLookY = 0.0;

    // Phase 1: Rapid printing of 10 consolidation candles on the left (0s - 2.0s)
    // Both consolidation series and the God Candle base are in full view
    if (t < 2.0) {
      const stepTime = 2.0 / CONSOLIDATION_SERIES.length;
      const count = Math.min(
        CONSOLIDATION_SERIES.length,
        Math.floor(t / stepTime) + 1
      );
      setVisibleCandles(count);
      setErupting(false);
      targetHeight.current = 0.12;
      setGain(Math.floor(120 + (t / 2.0) * 240));

      targetCamY = -0.15;
      targetCamZ = 4.9;
      targetLookY = -0.4;
    }
    // Phase 2: GOD CANDLE EXPLOSIVE GROWTH (2.0s - 6.8s)
    // Blasts from baseline up to 5.4 units tall! Camera ZOOMS OUT and elevates smoothly
    else if (t >= 2.0 && t < 6.8) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setErupting(true);

      const pumpProgress = Math.min(1, (t - 2.0) / 3.6);
      // Explosive acceleration curve
      const pumpCurve = 1 - Math.pow(1 - pumpProgress, 3.8);

      // COLOSSAL TOWER: GROWS UP TO 5.4 UNITS HIGH!
      targetHeight.current = 0.12 + pumpCurve * 5.28;

      // Exponential percentage ticker
      setGain(Math.floor(360 + Math.pow(pumpProgress, 2.6) * 64200));

      // Camera stays CENTERED at x = 0, elevates and zooms out so ALL candles stay in frame
      targetCamY = 0.45;
      targetCamZ = 5.9;
      targetLookY = 0.6;
    }
    // Phase 3: Stratosphere ATH Apex Hold (6.8s - 11.4s)
    else if (t >= 6.8 && t < 11.4) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setErupting(true);
      targetHeight.current = 5.40 + Math.sin(t * 3.5) * 0.18;

      targetCamY = 0.45;
      targetCamZ = 5.9;
      targetLookY = 0.6;
    }
    // Phase 4: Loop reset (11.4s - 12.0s)
    else {
      targetHeight.current = 0.12;
      targetCamY = -0.15;
      targetCamZ = 4.9;
      targetLookY = -0.4;
    }

    // Camera smoothing - KEEPS CAMERA CENTERED AT X = 0 (never pushes candles off-screen)
    const mouseParallaxX = state.pointer.x * 0.18;
    const mouseParallaxY = state.pointer.y * 0.10;

    state.camera.position.x += (mouseParallaxX - state.camera.position.x) * 0.08;
    state.camera.position.y += (targetCamY + mouseParallaxY - state.camera.position.y) * 0.08;
    state.camera.position.z += (targetCamZ - state.camera.position.z) * 0.08;
    // CRITICAL: Always look at center so camera yaw is never permanently rotated off-center
    state.camera.lookAt(0, targetLookY, 0);

    // Responsive lerp for visceral physical growth
    currentHeight.current += (targetHeight.current - currentHeight.current) * 0.15;
    const h = Math.max(0.08, currentHeight.current);

    // Update main God Candle body scale and anchor base at BASELINE_Y
    if (candleMesh.current) {
      candleMesh.current.scale.set(1, h, 1);
      candleMesh.current.position.y = BASELINE_Y + h / 2;
    }
    if (coreMesh.current) {
      coreMesh.current.scale.set(1, h * 0.98, 1);
      coreMesh.current.position.y = BASELINE_Y + h / 2;
    }
    if (wireFrameMesh.current) {
      wireFrameMesh.current.scale.set(1.02, h, 1.02);
      wireFrameMesh.current.position.y = BASELINE_Y + h / 2;
    }

    // Breakthrough shockwave pulse at current apex
    if (shockRingRef.current) {
      if (erupting && h > 1.0) {
        shockRingRef.current.scale.x += delta * 5.2;
        shockRingRef.current.scale.y += delta * 5.2;
        shockRingRef.current.material.opacity = Math.max(
          0,
          shockRingRef.current.material.opacity - delta * 1.5
        );
      } else {
        shockRingRef.current.scale.set(0.1, 0.1, 0.1);
        shockRingRef.current.material.opacity = 0.9;
      }
    }

    // Group subtle 3D rotational tilt
    if (group.current) {
      const targetTiltY = state.pointer.x * 0.16;
      group.current.rotation.y += (targetTiltY - group.current.rotation.y) * 0.08;
    }
  });

  const candleTopY = BASELINE_Y + currentHeight.current;

  function triggerExplosion() {
    animTime.current = 2.05; // Instant Mega Pump surge
  }

  return (
    <group ref={group} onClick={triggerExplosion} cursor="pointer">
      {/* Chart Grid Lines & Horizontal Resistance spanning full width */}
      <ChartGridLines candleHeight={candleTopY} />

      {/* Preceding Historical Consolidation Candlesticks (Safely framed on the left) */}
      <group>
        {CONSOLIDATION_SERIES.slice(0, visibleCandles).map((c, i) => {
          const posX = CONSOLIDATION_START_X + i * CONSOLIDATION_STEP;
          const bodyHeight = Math.max(0.06, Math.abs(c.close - c.open));
          const bodyY = (c.open + c.close) / 2;
          const wickHeight = Math.max(0.14, c.high - c.low);
          const wickY = (c.high + c.low) / 2;
          const color = c.green ? "#22C55E" : "#F43F5E";
          const emissive = c.green ? "#15803D" : "#BE123C";

          return (
            <group key={i} position={[posX, 0, 0]}>
              {/* Body */}
              <mesh position={[0, bodyY, 0]}>
                <boxGeometry args={[0.13, bodyHeight, 0.11]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.35}
                  roughness={0.25}
                  metalness={0.2}
                />
              </mesh>

              {/* Wick */}
              <mesh position={[0, wickY, 0]}>
                <cylinderGeometry args={[0.008, 0.008, wickHeight, 8]} />
                <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={0.4} />
              </mesh>

              {/* Volume Bar */}
              <mesh position={[0, -1.33 + c.vol / 2, 0]}>
                <boxGeometry args={[0.13, c.vol, 0.11]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.25}
                  transparent
                  opacity={0.65}
                />
              </mesh>
            </group>
          );
        })}
      </group>

      {/* ================= THE TOWERING GIGANTIC GOD CANDLE ================= */}
      {/* Positioned dead-center at x = 0.0, commanding the entire hero stage */}
      <group position={[GOD_CANDLE_X, 0, 0]}>
        {/* Massive Volume Foundation Pillar Below Baseline */}
        <mesh position={[0, -1.02, 0]}>
          <boxGeometry args={[GOD_CANDLE_WIDTH, 0.62, GOD_CANDLE_DEPTH]} />
          <meshStandardMaterial
            color="#22C55E"
            emissive="#15803D"
            emissiveIntensity={0.8}
            roughness={0.16}
            metalness={0.35}
          />
        </mesh>

        {/* Lower Wick Piercing Deep into the Bedrock */}
        <mesh position={[0, BASELINE_Y - 0.22, 0]}>
          <cylinderGeometry args={[0.032, 0.032, 0.44, 16]} />
          <meshStandardMaterial color="#22C55E" emissive="#15803D" emissiveIntensity={0.85} />
        </mesh>

        {/* GIGANTIC Emerald Crystal God Candle Body */}
        <mesh ref={candleMesh} position={[0, BASELINE_Y + 0.5, 0]}>
          <boxGeometry args={[GOD_CANDLE_WIDTH, 1, GOD_CANDLE_DEPTH]} />
          <meshPhysicalMaterial
            color="#00FFA3"
            emissive="#10B981"
            emissiveIntensity={erupting ? 1.15 : 0.75}
            roughness={0.08}
            metalness={0.18}
            transmission={0.62}
            thickness={1.1}
            ior={1.5}
            transparent
            opacity={0.95}
          />
        </mesh>

        {/* Inner Core Plasma Rod (Super-intense neon radiance inside) */}
        <mesh ref={coreMesh} position={[0, BASELINE_Y + 0.5, 0]}>
          <cylinderGeometry args={[0.16, 0.16, 1, 16]} />
          <meshBasicMaterial color="#FFFFFF" />
        </mesh>

        {/* Luminous Outer Beveled Frame */}
        <mesh ref={wireFrameMesh} position={[0, BASELINE_Y + 0.5, 0]}>
          <boxGeometry args={[GOD_CANDLE_WIDTH, 1, GOD_CANDLE_DEPTH]} />
          <meshBasicMaterial color="#6EE7B7" wireframe transparent opacity={0.4} />
        </mesh>

        {/* Upper Wick Piercing into Space */}
        <mesh position={[0, candleTopY + 0.5, 0]}>
          <cylinderGeometry args={[0.032, 0.032, 1.0, 16]} />
          <meshStandardMaterial
            color="#A7F3D0"
            emissive="#31E3AC"
            emissiveIntensity={2.0}
          />
        </mesh>

        {/* Apex Star Diamond Flare at the Soaring Summit */}
        <group position={[0, candleTopY + 1.0, 0]}>
          <mesh rotation={[0, 0, Math.PI / 4]}>
            <octahedronGeometry args={[0.18, 0]} />
            <meshBasicMaterial color="#FFFFFF" />
          </mesh>
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.18, 0.48, 36]} />
            <meshBasicMaterial color="#31E3AC" transparent opacity={0.92} />
          </mesh>
        </group>

        {/* Breakthrough Shockwave Ring */}
        <mesh
          ref={shockRingRef}
          position={[0, candleTopY, 0]}
          rotation={[-Math.PI / 2, 0, 0]}
        >
          <ringGeometry args={[0.45, 0.60, 42]} />
          <meshBasicMaterial color="#31E3AC" transparent opacity={0.85} />
        </mesh>

        {/* Intense Radial Point Light Casting Green Glow Over Entire Scene */}
        <pointLight
          position={[0, candleTopY * 0.75, 1.0]}
          intensity={erupting ? 6.5 : 3.0}
          color="#31E3AC"
          distance={8.5}
        />
      </group>

      {/* Floating 3D HUD Badge (Anchored on the right side of the centered monolith) */}
      <FloatingHudBadge
        position={[1.55, candleTopY - 0.25, 0.35]}
        gainPct={gain.toLocaleString()}
        isVisible={erupting && currentHeight.current > 1.0}
      />

      {/* Ascending Rocket Market Sparks */}
      <MarketSparkParticles count={180} erupting={erupting} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Root Scene with Guaranteed Constant 60fps Frameloop
// ---------------------------------------------------------------------------
export default function IntakeScene({ onReady }) {
  const { post } = usePerf();

  return (
    <Canvas
      dpr={[1, 1.5]}
      frameloop="always"
      gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [0, -0.15, 4.9], fov: 46 }}
      onCreated={({ gl }) => {
        gl.setClearColor("#06080D", 1);
        onReady?.();
      }}
    >
      <ambientLight intensity={0.7} />
      <directionalLight position={[4, 6, 4]} intensity={2.8} color="#FFFFFF" />
      <directionalLight position={[-4, 2, -1]} intensity={1.5} color="#059669" />

      <CinematicGodCandle />

      {post && (
        <EffectComposer disableNormalPass multisampling={0}>
          <Bloom
            intensity={0.75}
            luminanceThreshold={0.2}
            luminanceSmoothing={0.35}
            mipmapBlur
          />
        </EffectComposer>
      )}
    </Canvas>
  );
}

