import { useEffect, useMemo, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { EffectComposer, Bloom } from "@react-three/postprocessing";
import * as THREE from "three";
import { usePerf } from "../perf/PerfProvider.jsx";

// ---------------------------------------------------------------------------
// Historical Consolidation Candles (6 candles in accumulation chop)
// Sizing: width = 0.30, depth = 0.22, properly sized and legible
// Spaced from x = -1.75 to x = -0.25 (step = 0.30)
// God Candle sits at x = +0.25 (starts with identical width 0.30 & height ~0.24,
// then erupts straight up into the sky to height 5.0 while camera zooms out)
// ---------------------------------------------------------------------------
const CONSOLIDATION_SERIES = [
  { open: -0.94, close: -1.04, high: -0.90, low: -1.08, green: false, vol: 0.16 },
  { open: -1.04, close: -0.96, high: -0.92, low: -1.07, green: true,  vol: 0.22 },
  { open: -0.96, close: -1.01, high: -0.93, low: -1.05, green: false, vol: 0.14 },
  { open: -1.01, close: -0.92, high: -0.88, low: -1.03, green: true,  vol: 0.28 },
  { open: -0.92, close: -0.97, high: -0.89, low: -1.00, green: false, vol: 0.18 },
  { open: -0.97, close: -0.90, high: -0.85, low: -0.99, green: true,  vol: 0.34 },
];

const CANDLE_WIDTH = 0.30;
const CANDLE_DEPTH = 0.22;
const BASELINE_Y = -0.90;
const START_X = -1.65;
const STEP_X = 0.31;
const GOD_CANDLE_X = START_X + CONSOLIDATION_SERIES.length * STEP_X; // x = +0.21

// ---------------------------------------------------------------------------
