      {[
        [-0.14, -0.04],
        [0.05, 0.20],
        [0.14, -0.04],
        [0.05, -0.20],
      ].map(([px, py], i) => (
        <mesh key={i} position={[px, py, 0.03]}>
          <octahedronGeometry args={[0.036, 0]} />
          <meshStandardMaterial
            color="#10B981"
            emissive="#059669"
            emissiveIntensity={0.8}
            metalness={0.5}
            roughness={0.1}
          />
        </mesh>
      ))}
    </group>
  );
}

// ===========================================================================
// 11. FLAP: 3D Supersonic Articulated Cyber Wings & Anti-Snipe Shield
// ===========================================================================
function FlapCyberWings() {
  const group = useRef(null);
  useFrame((state) => {
    if (!group.current) return;
    group.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.9 + 11) * 0.22;
    group.current.position.y = Math.sin(state.clock.elapsedTime * 1.5 + 11) * 0.035;
  });

  return (
    <group ref={group}>
      {/* Central Hexagonal Anti-Sniper Energy Shield */}
      <mesh rotation={[0, 0, Math.PI / 6]}>
        <cylinderGeometry args={[0.16, 0.16, 0.04, 6]} />
        <meshStandardMaterial
          color="#38BDF8"
          emissive="#0284C7"
          emissiveIntensity={0.6}
          metalness={0.75}
          roughness={0.18}
        />
      </mesh>

      {/* Crosshair Reticle Center Ring */}
      <mesh position={[0, 0, 0.025]}>
        <ringGeometry args={[0.07, 0.09, 24]} />
        <meshBasicMaterial color="#F0F9FF" />
      </mesh>

      {/* Swept Cybernetic Titanium Wing Blades (Left Wing) */}
      <mesh position={[-0.22, 0.08, 0]} rotation={[0, 0, -0.45]}>
        <boxGeometry args={[0.24, 0.05, 0.03]} />
        <meshStandardMaterial color="#64748B" metalness={0.9} roughness={0.2} />
      </mesh>
      <mesh position={[-0.25, 0.01, 0]} rotation={[0, 0, -0.3]}>
        <boxGeometry args={[0.28, 0.045, 0.03]} />
        <meshStandardMaterial color="#F59E0B" metalness={0.9} roughness={0.2} />
      </mesh>

      {/* Swept Cybernetic Titanium Wing Blades (Right Wing) */}
      <mesh position={[0.22, 0.08, 0]} rotation={[0, 0, 0.45]}>
        <boxGeometry args={[0.24, 0.05, 0.03]} />
        <meshStandardMaterial color="#64748B" metalness={0.9} roughness={0.2} />
      </mesh>
      <mesh position={[0.25, 0.01, 0]} rotation={[0, 0, 0.3]}>
        <boxGeometry args={[0.28, 0.045, 0.03]} />
        <meshStandardMaterial color="#F59E0B" metalness={0.9} roughness={0.2} />
      </mesh>
    </group>
  );
}

// ===========================================================================
// 12-VENUE CAROUSEL RIG
// ===========================================================================
const VENUE_ACCENTS = [
  "#22C55E", // 0. Pump.fun (Mint Green)
  "#FF6B00", // 1. Meteora (Fiery Orange)
  "#00F5FF", // 2. Raydium (Electric Cyan)
  "#10B981", // 3. Bags (Emerald Gold)
  "#F59E0B", // 4. LetsBonk (Bonk Gold)
  "#34D399", // 5. StonkFun (Stonks Green)
  "#A3E635", // 6. Printr (Mint Lime)
  "#38BDF8", // 7. Anoncoin (Cyan Cipher)
  "#60A5FA", // 8. Surge (Plasma Blue)
  "#F43F5E", // 9. Clanker (Beacon Red)
  "#FCD34D", // 10. FourMeme (Clover Gold)
  "#38BDF8", // 11. Flap (Sky Shield)
];

const TOTAL_VENUES = 12;

function Rig({ focus }) {
  const group = useRef(null);
  const target = useRef(0);
  const { low } = usePerf();

  useEffect(() => {
    // Bring focused item directly to front-center
    target.current = -focus * ((Math.PI * 2) / TOTAL_VENUES);
  }, [focus]);

  useFrame((state) => {
    const node = group.current;
    if (!node) return;
    node.rotation.y += (target.current - node.rotation.y) * 0.10;
    node.rotation.x = state.pointer.y * 0.12;
    if (low) state.invalidate();
  });

  return (
    <group ref={group}>
      {Array.from({ length: TOTAL_VENUES }).map((_, index) => {
        const angle = (index / TOTAL_VENUES) * Math.PI * 2;
        const radius = 1.45;
        const x = Math.sin(angle) * radius;
        const z = Math.cos(angle) * radius;
        const accent = VENUE_ACCENTS[index];

        return (
          <group key={index} position={[x, 0, z]}>
            {/* 3D Model according to venue index */}
            {index === 0 && <PumpFunPill />}
            {index === 1 && <MeteoraMeteor />}
            {index === 2 && <RaydiumCrystal />}
            {index === 3 && <BagsLuxurySatchel />}
            {index === 4 && <LetsBonkHammer />}
            {index === 5 && <StonkFunRocket />}
            {index === 6 && <PrintrMachine />}
            {index === 7 && <AnoncoinMask />}
            {index === 8 && <SurgeLightning />}
            {index === 9 && <ClankerRobot />}
            {index === 10 && <FourMemeEmblem />}
            {index === 11 && <FlapCyberWings />}

            {/* Glowing Accent Pedestal Ring Underneath */}
            <mesh position={[0, -0.46, 0]} rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[0.24, 0.32, 32]} />
              <meshBasicMaterial
                color={accent}
                transparent
                opacity={focus === index ? 0.8 : 0.15}
              />
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

export default function VenueScene({ onReady, focus = 0 }) {
  const { low } = usePerf();
  return (
    <Canvas
      dpr={low ? 1 : [1, 1.5]}
      frameloop={low ? "demand" : "always"}
      gl={{ antialias: !low, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [0, 0.45, 3.4], fov: 42 }}
      onCreated={({ gl, invalidate }) => {
        gl.setClearColor("#0B0F17", 1);
        onReady?.();
        invalidate();
      }}
    >
      <ambientLight intensity={0.8} />
      <directionalLight position={[3, 5, 4]} intensity={2.6} />
      <directionalLight position={[-4, 2, -1]} intensity={1.2} color="#38BDF8" />
      <pointLight position={[0, -0.2, 1.8]} intensity={1.5} color="#FF6B00" />
      <Rig focus={focus} />
    </Canvas>
  );
}

