import { useEffect, useMemo, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { EffectComposer, Bloom } from "@react-three/postprocessing";
import * as THREE from "three";
import { usePerf } from "../perf/PerfProvider.jsx";

// ---------------------------------------------------------------------------
// 6 Consolidation Candlesticks (Accumulation chop leading into God Candle)
// Positioned safely across the center-left: from x = -1.60 to x = -0.10
// Sizing: width = 0.22, depth = 0.18, step = 0.30
// God Candle sits at x = +0.35, initially matching this same size, then shoots to ATH!
// ---------------------------------------------------------------------------
const CONSOLIDATION_SERIES = [
  { open: -0.72, close: -0.86, high: -0.66, low: -0.92, green: false, vol: 0.18 },
  { open: -0.86, close: -0.74, high: -0.68, low: -0.90, green: true,  vol: 0.24 },
  { open: -0.74, close: -0.82, high: -0.70, low: -0.88, green: false, vol: 0.16 },
  { open: -0.82, close: -0.70, high: -0.64, low: -0.86, green: true,  vol: 0.30 },
  { open: -0.70, close: -0.78, high: -0.66, low: -0.84, green: false, vol: 0.20 },
  { open: -0.78, close: -0.68, high: -0.60, low: -0.82, green: true,  vol: 0.36 },
];

const START_X = -1.55;
const STEP_X = 0.30;
const BASELINE_Y = -0.78;
const GOD_CANDLE_X = START_X + CONSOLIDATION_SERIES.length * STEP_X; // x = +0.25

// ---------------------------------------------------------------------------
// Chart Grid & Stratospheric Resistance Levels
// Symmetrically crosses the entire viewport
// ---------------------------------------------------------------------------
function ChartGridLines({ candleHeight }) {
  const levels = [
    { y: -1.05, label: "GROUND ACCUMULATION ($0.01)", color: "#334155" },
    { y: -0.68, label: "BREAKOUT BASELINE ($0.10)", color: "#475569" },
    { y: 0.25,  label: "RESISTANCE 1 ($1.00) [SHATTERED]", color: "#059669" },
    { y: 1.15,  label: "RESISTANCE 2 ($10.0) [SHATTERED]", color: "#10B981" },
    { y: 2.05,  label: "STRATOSPHERE ATH ($100.0) [BROKEN]", color: "#31E3AC" },
    { y: 2.75,  label: "ORBITAL ESCAPE ($1000.0+)", color: "#86EFAC" },
  ];

  return (
    <group position={[0, 0, -0.2]}>
      {levels.map((lvl, idx) => {
        const breached = candleHeight > lvl.y;
        return (
          <group key={idx} position={[0, lvl.y, 0]}>
            <mesh>
              <boxGeometry args={[10.5, 0.012, 0.012]} />
              <meshBasicMaterial
                color={breached ? lvl.color : "#1E293B"}
                transparent
                opacity={breached ? 0.9 : 0.22}
              />
            </mesh>
          </group>
        );
      })}

      {/* Deep Ground Grid Base */}
      <mesh position={[0, -1.08, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[11.0, 3.8]} />
        <meshBasicMaterial color="#06080E" />
      </mesh>
      <gridHelper args={[11.0, 24, "#1E293B", "#0C121D"]} position={[0, -1.075, 0]} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Ascending Rocket Fuel Market Sparks
// ---------------------------------------------------------------------------
function MarketSparkParticles({ count = 160, erupting }) {
  const pointsRef = useRef(null);
  const { low } = usePerf();
  const actualCount = low ? 45 : count;

  const [positions, speeds, colors] = useMemo(() => {
    const pos = new Float32Array(actualCount * 3);
    const spd = new Float32Array(actualCount);
    const col = new Float32Array(actualCount * 3);

    const cNeon = new THREE.Color("#31E3AC");
    const cGreen = new THREE.Color("#22C55E");
    const cGold = new THREE.Color("#FCD34D");
    const cWhite = new THREE.Color("#FFFFFF");

    for (let i = 0; i < actualCount; i++) {
      const radX = (Math.random() - 0.5) * 3.4;
      const radZ = (Math.random() - 0.5) * 1.6;
      pos[i * 3] = radX;
      pos[i * 3 + 1] = -1.1 + Math.random() * 4.6;
      pos[i * 3 + 2] = radZ;

      spd[i] = 0.02 + Math.random() * 0.06;

      const pick = Math.random();
      const chosen = pick > 0.8 ? cWhite : pick > 0.6 ? cGold : pick > 0.25 ? cNeon : cGreen;
      col[i * 3] = chosen.r;
      col[i * 3 + 1] = chosen.g;
      col[i * 3 + 2] = chosen.b;
    }
    return [pos, spd, col];
  }, [actualCount, low]);

  useFrame((_, delta) => {
    if (!pointsRef.current) return;
    const geo = pointsRef.current.geometry;
    const posAttr = geo.attributes.position;
    const mult = erupting ? 4.5 : 1.2;

    for (let i = 0; i < actualCount; i++) {
      let y = posAttr.getY(i) + speeds[i] * (delta * 60) * mult;
      if (y > 3.8) {
        y = -1.1 - Math.random() * 0.2;
      }
      posAttr.setY(i, y);
    }
    posAttr.needsUpdate = true;
  });

  return (
    <points ref={pointsRef}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-color" args={[colors, 3]} />
      </bufferGeometry>
      <pointsMaterial
        size={low ? 0.05 : 0.04}
        vertexColors
        transparent
        opacity={erupting ? 0.95 : 0.5}
        sizeAttenuation
      />
    </points>
  );
}

// ---------------------------------------------------------------------------
// 3D Floating HUD Banner (From the beloved 7:36 PM version)
// ---------------------------------------------------------------------------
function FloatingHudBadge({ position, gainPct, isVisible }) {
  const meshRef = useRef(null);

  const texture = useMemo(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 280;
    canvas.height = 130;
    const ctx = canvas.getContext("2d");

    ctx.fillStyle = "rgba(7, 10, 16, 0.96)";
    ctx.beginPath();
    ctx.roundRect(4, 4, 272, 122, 12);
    ctx.fill();

    ctx.lineWidth = 3.5;
    ctx.strokeStyle = "#31E3AC";
    ctx.stroke();

    ctx.fillStyle = "#31E3AC";
    ctx.font = "900 36px monospace";
    ctx.fillText(`▲ +${gainPct}%`, 16, 46);

    ctx.fillStyle = "#F8FAFC";
    ctx.font = "bold 18px monospace";
    ctx.fillText("GOD CANDLE ATH", 16, 80);

    ctx.fillStyle = "#94A3B8";
    ctx.font = "bold 14px monospace";
    ctx.fillText("VOL: 2,450,000 SOL", 16, 110);

    const tex = new THREE.CanvasTexture(canvas);
    tex.needsUpdate = true;
    return tex;
  }, [gainPct]);

  useFrame((state) => {
    if (!meshRef.current) return;
    meshRef.current.position.y = position[1] + Math.sin(state.clock.elapsedTime * 2.2) * 0.04;
    meshRef.current.scale.setScalar(isVisible ? 1 : 0);
  });

  return (
    <mesh ref={meshRef} position={position}>
      <planeGeometry args={[1.25, 0.58]} />
      <meshBasicMaterial map={texture} transparent opacity={0.98} side={THREE.DoubleSide} />
    </mesh>
  );
}

// ---------------------------------------------------------------------------
// Main Cinematic God Candle Chart
// ---------------------------------------------------------------------------
function CinematicGodCandle() {
  const group = useRef(null);
  const candleMesh = useRef(null);
  const coreMesh = useRef(null);
  const wireFrameMesh = useRef(null);
  const shockRingRef = useRef(null);

  // Timing
  const animTime = useRef(0);
  const [visibleCandles, setVisibleCandles] = useState(0);
  const [erupting, setErupting] = useState(false);
  const [gain, setGain] = useState(140);

  // Starts as normal green candle height: 0.24
  const INITIAL_HEIGHT = 0.24;
  const currentHeight = useRef(INITIAL_HEIGHT);
  const targetHeight = useRef(INITIAL_HEIGHT);

  const CYCLE_DURATION = 12.0;

  useFrame((state, delta) => {
    animTime.current += delta;
    const t = animTime.current % CYCLE_DURATION;

    let targetCamX = -0.15;
    let targetCamY = -0.25;
    let targetCamZ = 3.6; // Starts close up so the consolidation candles are large & clear!
    let targetLookY = -0.45;

    // Phase 1: Rapid printing of consolidation candles (0s - 2.0s)
    if (t < 2.0) {
      const stepTime = 2.0 / CONSOLIDATION_SERIES.length;
      const count = Math.min(
        CONSOLIDATION_SERIES.length,
        Math.floor(t / stepTime) + 1
      );
      setVisibleCandles(count);
      setErupting(false);
      targetHeight.current = INITIAL_HEIGHT; // Exact same size as the other green candles!
      setGain(Math.floor(100 + (t / 2.0) * 180));

      targetCamX = -0.15;
      targetCamY = -0.25;
      targetCamZ = 3.6;
      targetLookY = -0.45;
    }
    // Phase 2: GOD CANDLE EXPLOSIVE ASCENT & CAMERA ZOOMS OUT (2.0s - 6.8s)
    else if (t >= 2.0 && t < 6.8) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setErupting(true);

      const pumpProgress = Math.min(1, (t - 2.0) / 3.6);
      const pumpCurve = 1 - Math.pow(1 - pumpProgress, 3.6);

      // Shoots from 0.24 up to 3.25 units high! (Fills screen without being cut off)
      targetHeight.current = INITIAL_HEIGHT + pumpCurve * 3.01;

      setGain(Math.floor(280 + Math.pow(pumpProgress, 2.7) * 48200));

      // As it gets taller, the camera smoothly ZOOMS OUT from z=3.6 to z=5.2
      // and elevates to keep BOTH the bottom candles and towering tip in frame!
      targetCamX = -0.05;
      targetCamY = 0.35;
      targetCamZ = 5.2;
      targetLookY = 0.35;
    }
    // Phase 3: Stratosphere ATH Hold (6.8s - 11.4s)
    else if (t >= 6.8 && t < 11.4) {
      setVisibleCandles(CONSOLIDATION_SERIES.length);
      setErupting(true);
      targetHeight.current = 3.25 + Math.sin(t * 3.2) * 0.10;

      targetCamX = -0.05;
      targetCamY = 0.35;
      targetCamZ = 5.2;
      targetLookY = 0.35;
    }
    // Phase 4: Loop reset (11.4s - 12.0s)
    else {
      targetHeight.current = INITIAL_HEIGHT;
      targetCamX = -0.15;
      targetCamY = -0.25;
      targetCamZ = 3.6;
      targetLookY = -0.45;
    }

    // Camera smoothing with mouse parallax
    const mouseX = state.pointer.x * 0.10;
    const mouseY = state.pointer.y * 0.06;

    state.camera.position.x += (targetCamX + mouseX - state.camera.position.x) * 0.08;
    state.camera.position.y += (targetCamY + mouseY - state.camera.position.y) * 0.08;
    state.camera.position.z += (targetCamZ - state.camera.position.z) * 0.08;

    // Guaranteed lookAt every frame so camera yaw/pitch stays rock-solid centered
    state.camera.lookAt(targetCamX * 0.5, targetLookY, 0);

    // Responsive growth lerp
    currentHeight.current += (targetHeight.current - currentHeight.current) * 0.15;
    const h = Math.max(INITIAL_HEIGHT, currentHeight.current);

    // Scale candle mesh
    if (candleMesh.current) {
      candleMesh.current.scale.set(1, h, 1);
      candleMesh.current.position.y = BASELINE_Y + h / 2;
    }
    if (coreMesh.current) {
      coreMesh.current.scale.set(1, h * 0.98, 1);
      coreMesh.current.position.y = BASELINE_Y + h / 2;
    }
    if (wireFrameMesh.current) {
      wireFrameMesh.current.scale.set(1.02, h, 1.02);
      wireFrameMesh.current.position.y = BASELINE_Y + h / 2;
    }

    // Shockwave pulse at tip
    if (shockRingRef.current) {
      if (erupting && h > 0.8) {
        shockRingRef.current.scale.x += delta * 4.5;
        shockRingRef.current.scale.y += delta * 4.5;
        shockRingRef.current.material.opacity = Math.max(
          0,
          shockRingRef.current.material.opacity - delta * 1.5
        );
      } else {
        shockRingRef.current.scale.set(0.1, 0.1, 0.1);
        shockRingRef.current.material.opacity = 0.9;
      }
    }

    // Subtle group tilt
    if (group.current) {
      const tilt = state.pointer.x * 0.05;
      group.current.rotation.y += (tilt - group.current.rotation.y) * 0.06;
    }
  });

  const candleTopY = BASELINE_Y + currentHeight.current;

  function triggerExplosion() {
    animTime.current = 2.05;
  }

  return (
    <group ref={group} onClick={triggerExplosion} cursor="pointer">
      {/* Chart Grid Lines & Horizontal Resistance */}
      <ChartGridLines candleHeight={candleTopY} />

      {/* Preceding Historical Consolidation Candlesticks (Prominently framed on left) */}
      <group>
        {CONSOLIDATION_SERIES.slice(0, visibleCandles).map((c, i) => {
          const posX = START_X + i * STEP_X;
          const bodyHeight = Math.max(0.10, Math.abs(c.close - c.open));
          const bodyY = (c.open + c.close) / 2;
          const wickHeight = Math.max(0.24, c.high - c.low);
          const wickY = (c.high + c.low) / 2;
          const color = c.green ? "#22C55E" : "#F43F5E";
          const emissive = c.green ? "#15803D" : "#BE123C";

          return (
            <group key={i} position={[posX, 0, 0]}>
              {/* Candle Body */}
              <mesh position={[0, bodyY, 0]}>
                <boxGeometry args={[0.22, bodyHeight, 0.16]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.35}
                  roughness={0.25}
                  metalness={0.2}
                />
              </mesh>

              {/* Wick */}
              <mesh position={[0, wickY, 0]}>
                <cylinderGeometry args={[0.010, 0.010, wickHeight, 8]} />
                <meshStandardMaterial color={color} emissive={emissive} emissiveIntensity={0.4} />
              </mesh>

              {/* Volume Bar Underneath */}
              <mesh position={[0, -1.06 + c.vol / 2, 0]}>
                <boxGeometry args={[0.22, c.vol, 0.16]} />
                <meshStandardMaterial
                  color={color}
                  emissive={emissive}
                  emissiveIntensity={0.25}
                  transparent
                  opacity={0.65}
                />
              </mesh>
            </group>
          );
        })}
      </group>

      {/* ================= THE GOD CANDLE ================= */}
      {/* From the beloved 7:36 PM screenshot: Emerald Crystal with Core Rod & Wireframe */}
      <group position={[GOD_CANDLE_X, 0, 0]}>
        {/* Foundation Volume Pillar */}
        <mesh position={[0, -0.92, 0]}>
          <boxGeometry args={[0.54, 0.36, 0.34]} />
          <meshStandardMaterial
            color="#22C55E"
            emissive="#15803D"
            emissiveIntensity={0.75}
            roughness={0.18}
            metalness={0.3}
          />
        </mesh>

        {/* Lower Wick */}
        <mesh position={[0, BASELINE_Y - 0.16, 0]}>
          <cylinderGeometry args={[0.018, 0.018, 0.32, 16]} />
          <meshStandardMaterial color="#22C55E" emissive="#15803D" emissiveIntensity={0.8} />
        </mesh>

        {/* Dynamic God Candle Body (Emerald Crystal) */}
        <mesh ref={candleMesh} position={[0, BASELINE_Y + INITIAL_HEIGHT / 2, 0]}>
          <boxGeometry args={[0.54, 1, 0.36]} />
          <meshPhysicalMaterial
            color="#00FFA3"
            emissive="#10B981"
            emissiveIntensity={erupting ? 1.1 : 0.7}
            roughness={0.10}
            metalness={0.15}
            transmission={0.65}
            thickness={0.8}
            ior={1.48}
            transparent
            opacity={0.94}
          />
        </mesh>

        {/* Inner Core Plasma Rod (Pours intense light up the center) */}
        <mesh ref={coreMesh} position={[0, BASELINE_Y + INITIAL_HEIGHT / 2, 0]}>
          <cylinderGeometry args={[0.07, 0.07, 1, 16]} />
          <meshBasicMaterial color="#F0FDF4" />
        </mesh>

        {/* Luminous Beveled Edge Frame */}
        <mesh ref={wireFrameMesh} position={[0, BASELINE_Y + INITIAL_HEIGHT / 2, 0]}>
          <boxGeometry args={[0.54, 1, 0.36]} />
          <meshBasicMaterial color="#A7F3D0" wireframe transparent opacity={0.45} />
        </mesh>

        {/* Upper Wick Piercing into Space */}
        <mesh position={[0, candleTopY + 0.30, 0]}>
          <cylinderGeometry args={[0.018, 0.018, 0.60, 16]} />
          <meshStandardMaterial
            color="#A7F3D0"
            emissive="#31E3AC"
            emissiveIntensity={1.8}
          />
        </mesh>

        {/* Apex Star Diamond Flare at the Soaring Summit */}
        <group position={[0, candleTopY + 0.60, 0]}>
          <mesh rotation={[0, 0, Math.PI / 4]}>
            <octahedronGeometry args={[0.12, 0]} />
            <meshBasicMaterial color="#FFFFFF" />
          </mesh>
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.11, 0.32, 32]} />
            <meshBasicMaterial color="#31E3AC" transparent opacity={0.9} />
          </mesh>
        </group>

        {/* Breakthrough Shockwave Ring */}
        <mesh
          ref={shockRingRef}
          position={[0, candleTopY, 0]}
          rotation={[-Math.PI / 2, 0, 0]}
        >
          <ringGeometry args={[0.30, 0.40, 36]} />
          <meshBasicMaterial color="#31E3AC" transparent opacity={0.85} />
        </mesh>

        {/* Radial Point Light Lighting Up the Stage */}
        <pointLight
          position={[0, candleTopY * 0.7, 0.8]}
          intensity={erupting ? 5.5 : 2.2}
          color="#31E3AC"
          distance={7.5}
        />
      </group>

      {/* Floating 3D HUD Badge (Docked smoothly on the right of the God Candle) */}
      <FloatingHudBadge
        position={[GOD_CANDLE_X + 0.95, Math.min(2.2, candleTopY - 0.15), 0.3]}
        gainPct={gain.toLocaleString()}
        isVisible={erupting && currentHeight.current > 0.6}
      />

      {/* Ascending Rocket Market Sparks */}
      <MarketSparkParticles count={160} erupting={erupting} />
    </group>
  );
}

// ---------------------------------------------------------------------------
// Root Scene with Guaranteed Constant 60fps Frameloop
// ---------------------------------------------------------------------------
export default function IntakeScene({ onReady }) {
  const { post } = usePerf();

  return (
    <Canvas
      dpr={[1, 1.5]}
      frameloop="always"
      gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [-0.15, -0.25, 3.6], fov: 44 }}
      onCreated={({ gl }) => {
        gl.setClearColor("#06080E", 1);
        onReady?.();
      }}
    >
      <ambientLight intensity={0.7} />
      <directionalLight position={[4, 6, 4]} intensity={2.8} color="#FFFFFF" />
      <directionalLight position={[-4, 2, -1]} intensity={1.5} color="#059669" />

      <CinematicGodCandle />

      {post && (
        <EffectComposer disableNormalPass multisampling={0}>
          <Bloom
            intensity={0.75}
            luminanceThreshold={0.2}
            luminanceSmoothing={0.35}
            mipmapBlur
          />
        </EffectComposer>
      )}
    </Canvas>
  );
}

