// ===========================================================================
// 12-VENUE CAROUSEL RIG
// ===========================================================================
const VENUE_ACCENTS = [
  "#22C55E", // 0. Pump.fun (Mint Green)
  "#FF6B00", // 1. Meteora (Fiery Orange)
  "#00F5FF", // 2. Raydium (Electric Cyan)
  "#00E676", // 3. Bags (Money Green)
  "#F59E0B", // 4. LetsBonk (Bonk Gold)
  "#34D399", // 5. StonkFun (Stonks Green)
  "#A3E635", // 6. Printr (Mint Lime)
  "#38BDF8", // 7. Anoncoin (Cyan Cipher)
  "#60A5FA", // 8. Surge (Plasma Blue)
  "#F43F5E", // 9. Clanker (Beacon Red)
  "#FCD34D", // 10. FourMeme (Clover Gold)
  "#38BDF8", // 11. Flap (Sky Shield)
];

const TOTAL_VENUES = 12;

function Rig({ focus }) {
  const group = useRef(null);
  const target = useRef(0);
  const { low } = usePerf();

  useEffect(() => {
    target.current = -focus * ((Math.PI * 2) / TOTAL_VENUES);
  }, [focus]);

  useFrame((state) => {
    const node = group.current;
    if (!node) return;
    node.rotation.y += (target.current - node.rotation.y) * 0.10;
    node.rotation.x = state.pointer.y * 0.12;
    if (low) state.invalidate();
  });

  return (
    <group ref={group}>
      {Array.from({ length: TOTAL_VENUES }).map((_, index) => {
        const angle = (index / TOTAL_VENUES) * Math.PI * 2;
        const radius = 1.45;
        const x = Math.sin(angle) * radius;
        const z = Math.cos(angle) * radius;
        const accent = VENUE_ACCENTS[index];

        return (
          <group key={index} position={[x, 0, z]}>
            {/* 3D Model according to venue index */}
            {index === 0 && <PumpFunPill />}
            {index === 1 && <MeteoraMeteor />}
            {index === 2 && <RaydiumCrystal />}
            {index === 3 && <BagsMoneyBag />}
            {index === 4 && <LetsBonkHammer />}
            {index === 5 && <StonkFunRocket />}
            {index === 6 && <PrintrMachine />}
            {index === 7 && <AnoncoinMask />}
            {index === 8 && <SurgeLightning />}
            {index === 9 && <ClankerRobot />}
            {index === 10 && <FourMemeEmblem />}
            {index === 11 && <FlapCyberWings />}

            {/* Glowing Accent Pedestal Ring Underneath */}
            <mesh position={[0, -0.46, 0]} rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[0.24, 0.32, 32]} />
              <meshBasicMaterial
                color={accent}
                transparent
                opacity={focus === index ? 0.8 : 0.15}
              />
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

export default function VenueScene({ onReady, focus = 0 }) {
  const { low } = usePerf();
  return (
    <Canvas
      dpr={low ? 1 : [1, 1.5]}
      frameloop={low ? "demand" : "always"}
      gl={{ antialias: !low, alpha: true, powerPreference: "high-performance" }}
      camera={{ position: [0, 0.45, 3.4], fov: 42 }}
      onCreated={({ gl, invalidate }) => {
        gl.setClearColor("#0B0F17", 1);
        onReady?.();
        invalidate();
      }}
    >
      <ambientLight intensity={0.8} />
      <directionalLight position={[3, 5, 4]} intensity={2.6} />
      <directionalLight position={[-4, 2, -1]} intensity={1.2} color="#38BDF8" />
      <pointLight position={[0, -0.2, 1.8]} intensity={1.5} color="#FF6B00" />
      <Rig focus={focus} />
    </Canvas>
  );
}

