import { useEffect, useMemo, useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { SVGLoader } from "three/examples/jsm/loaders/SVGLoader.js";
import { usePerf } from "../perf/PerfProvider.jsx";

// Helper to safely parse an SVG path into Three.js ExtrudeGeometry
function createExtrudedSvg(svgString, extrudeSettings) {
  try {
    if (typeof window !== "undefined" && window.DOMParser) {
      const loader = new SVGLoader();
      const parsed = loader.parse(svgString);
      const shapes = parsed.paths.flatMap((p) => SVGLoader.createShapes(p));
      if (shapes.length > 0) {
        const geo = new THREE.ExtrudeGeometry(shapes, extrudeSettings);
        geo.center();
        return geo;
      }
    }
  } catch (e) {
    console.warn("SVG extrude error, fallback used:", e);
  }
  return null;
}

// ===========================================================================
// 0. PUMP.FUN: 3D Mint & White Capsule Pill (User Favorite!)
// ===========================================================================
function PumpFunPill() {
  const group = useRef(null);
  useFrame((state) => {
    if (!group.current) return;
    group.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.9) * 0.22;
    group.current.position.y = Math.sin(state.clock.elapsedTime * 1.6) * 0.035;
