  flex-direction: column;
  gap: 1rem;
}

.tacho-summary h3 { font-size: 0.95rem; margin: 0 0 0.4rem; color: var(--stark); }
.tacho-summary p { font-size: 0.8rem; color: var(--muted); line-height: 1.4; margin: 0; }

.boost-btn {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.76rem;
  padding: 0.6rem 1.2rem;
  background: rgba(255, 62, 0, 0.2);
  border: 1px solid var(--plasma);
  color: var(--plasma);
  border-radius: 4px;
  cursor: pointer;
}

/* 11. Atomic Clock */
.clock-box {
  background: rgba(11, 15, 23, 0.6);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.clock-header {
  display: flex;
  justify-content: space-between;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.72rem;
  margin-bottom: 0.6rem;
}

.slot-badge { color: var(--mint); font-weight: 700; }
.time-badge { color: var(--muted); }

.slot-track {
  display: flex;
  width: 100%;
  height: 52px;
  background: rgba(8, 9, 12, 0.8);
  border: 1px solid var(--line);
  border-radius: 6px;
  overflow: hidden;
}

.phase-chunk {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border-right: 1px solid var(--line);
  cursor: pointer;
  padding: 0.2rem;
  font-family: "JetBrains Mono", monospace;
  transition: all 0.15s ease;
}

.phase-chunk:last-child { border-right: none; }
.phase-chunk.selected { background: rgba(34, 197, 94, 0.25); }

.chunk-label { font-size: 0.62rem; color: var(--mint); font-weight: 700; }
.chunk-name { font-size: 0.65rem; color: var(--stark); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 90%; }

.phase-card {
  background: rgba(8, 9, 12, 0.8);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1.2rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.phase-badge { font-family: "JetBrains Mono", monospace; font-size: 0.68rem; color: var(--mint); }
.phase-title { font-size: 0.95rem; font-weight: 700; color: var(--stark); margin: 0; }
.phase-desc { font-size: 0.8rem; color: var(--muted); line-height: 1.4; margin: 0; }

/* 12. Plasma Nozzle */
.nozzle-box {
  background: rgba(11, 15, 23, 0.6);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

.nozzle-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.74rem;
  gap: 1rem;
}

.nozzle-slider { width: 220px; accent-color: var(--mint); }
.nozzle-readout { display: flex; gap: 1rem; color: var(--mint); }

.nozzle-graphic {
  width: 100%;
  height: 160px;
  background: rgba(8, 9, 12, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 4px;
}

.nozzle-svg { width: 100%; height: 100%; }

/* 13. Stealth Payload */
.stealth-box {
  background: rgba(11, 15, 23, 0.6);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 2rem;
}

.stealth-intro h3 { font-size: 0.95rem; margin: 0 0 0.4rem; color: var(--stark); }
.stealth-intro p { font-size: 0.8rem; color: var(--muted); line-height: 1.4; margin: 0; }

.vault-interface {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
  min-width: 280px;
}

.vault-key-display {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-family: "JetBrains Mono", monospace;
  background: rgba(8, 9, 12, 0.8);
  border: 1px solid var(--line);
  padding: 0.8rem;
  border-radius: 4px;
}

.key-lbl { font-size: 0.65rem; color: var(--muted); }
.key-val { font-size: 1.1rem; font-weight: 700; color: #38BDF8; }
.key-badge { font-size: 0.65rem; color: var(--mint); }

