  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

.router-head .router-lede { font-size: 0.85rem; color: var(--muted); margin: 0; }

.router-matrix {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.8rem;
}

.venue-card {
  background: rgba(8, 9, 12, 0.8);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  cursor: pointer;
  transition: all 0.15s ease;
}

.venue-card.active {
