  box-shadow: 0 0 12px rgba(34, 197, 94, 0.2);
}

.venue-card .card-top { display: flex; justify-content: space-between; font-weight: 700; font-size: 0.82rem; color: var(--stark); }
.venue-card .v-lat { color: var(--mint); font-family: "JetBrains Mono", monospace; font-size: 0.72rem; }
.venue-card .v-type { font-size: 0.68rem; color: var(--muted); }
.venue-card .card-bot { display: flex; justify-content: space-between; font-family: "JetBrains Mono", monospace; font-size: 0.65rem; margin-top: 0.4rem; }
.venue-card .v-fee { color: #F59E0B; }
.venue-card .v-rate { color: var(--mint); font-weight: 700; }

.router-terminal {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.76rem;
  color: var(--mint);
  background: rgba(8, 9, 12, 0.8);
  padding: 0.6rem 1rem;
  border-radius: 4px;
  border: 1px solid var(--line);
}

/* 15. Ablation Shield */
.ablation-box {
  background: rgba(11, 15, 23, 0.6);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

.ablation-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.74rem;
  gap: 1rem;
}

.friction-slider { width: 220px; accent-color: var(--plasma); }
.temp-readout { display: flex; gap: 1rem; color: var(--plasma); font-weight: 700; }

.hex-tile-grid {
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: 8px;
  padding: 1rem;
  background: #08090C;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.hex-tile {
  height: 48px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  transition: all 0.25s ease;
}

@media (max-width: 900px) {
  .radar-layout { grid-template-columns: 1fr; }
