      targetCamY = -0.22;
      targetCamZ = 4.2;
      targetLookY = -0.45;
    }
    // Phase 2: Candle 7 (God Candle) appears at SAME EXACT WIDTH & COLOR (2.2s - 2.5s)
    else if (t >= 2.2 && t < 2.5) {
