                {/* Live Hypersonic Telemetry Badge at Flat Apex */}
                <text
                  x="212"
                  y={candleTopY - 4}
                  fill="#31E3AC"
                  fontSize="9.5"
                  fontFamily="JetBrains Mono"
                  fontWeight="bold"
                >
