1: import { Keypair, PublicKey, SystemProgram, TransactionInstruction } from "@solana/web3.js";
2: import { GhostFunderConfig, SubWallet } from "../../types";
3: 
4: export interface DispersalPlan {
5:   masterPayer: PublicKey;
6:   totalSolRequired: number;
7:   relays: {
8:     relayKeypair: Keypair;
9:     targetWallets: SubWallet[];
10:     relayFundingSol: number;
11:   }[];
12:   instructions: TransactionInstruction[];
13: }
14: 
15: export class GhostFunder {
16:   /**
17:    * Plans multi-hop relay dispersion to prevent single-parent clustering on BubbleMaps.
18:    * Splits N sub-wallets across intermediate relay accounts with randomized timing and non-round amounts.
19:    */
20:   public static planGhostDispersal(params: {
21:     masterPayer: PublicKey;
22:     subWallets: SubWallet[];
23:     config: GhostFunderConfig;
24:   }): DispersalPlan {
25:     const { masterPayer, subWallets, config } = params;
26:     const RELAYS_COUNT = Math.max(2, Math.ceil(subWallets.length / 5));
27:     const relays: DispersalPlan["relays"] = [];
28: 
29:     for (let r = 0; r < RELAYS_COUNT; r++) {
30:       relays.push({
31:         relayKeypair: Keypair.generate(),
32:         targetWallets: [],
33:         relayFundingSol: 0,
34:       });
35:     }
36: 
37:     // Distribute sub-wallets across relays with randomized jitter
38:     let totalSolRequired = 0;
39:     subWallets.forEach((wallet, idx) => {
40:       const relay = relays[idx % RELAYS_COUNT];
41:       
42:       // Calculate randomized jitter (e.g. ±5%) to avoid round number detection
43:       const jitterFactor = 1 + (Math.random() * 2 - 1) * (config.randomDeviationPercent / 100);
44:       const allocatedSol = Number((wallet.allocatedBuySol * jitterFactor).toFixed(4));
45: 
46:       relay.targetWallets.push({
47:         ...wallet,
48:         allocatedBuySol: allocatedSol,
49:       });
50: 
51:       // Include base rent buffer (0.01 SOL)
52:       relay.relayFundingSol += allocatedSol + 0.01;
53:       totalSolRequired += allocatedSol + 0.01;
54:     });
55: 
56:     // Generate Level 1 Instructions: Master Payer -> Relays
57:     const instructions: TransactionInstruction[] = relays.map((r) =>
58:       SystemProgram.transfer({
59:         fromPubkey: masterPayer,
60:         toPubkey: r.relayKeypair.publicKey,
61:         lamports: BigInt(Math.floor(r.relayFundingSol * 1e9)),
62:       })
63:     );
64: 
65:     return {
66:       masterPayer,
67:       totalSolRequired: Number(totalSolRequired.toFixed(4)),
68:       relays,
69:       instructions,
70:     };
71:   }
72: }

