import { useEffect } from "react";
import Lenis from "lenis";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { usePerf } from "../perf/PerfProvider";

if (typeof window !== "undefined") {
  gsap.registerPlugin(ScrollTrigger);
}

export function SmoothScroll() {
  const { motionOff, low } = usePerf();

  useEffect(() => {
    if (motionOff || typeof window === "undefined") return undefined;

    const lenis = new Lenis({
      lerp: low ? 0.16 : 0.09,
      smoothWheel: true,
      autoRaf: false,
    });

    lenis.on("scroll", ScrollTrigger.update);
    const tick = (time: number) => {
      lenis.raf(time * 1000);
    };

    gsap.ticker.add(tick);
    gsap.ticker.lagSmoothing(0);

    return () => {
      gsap.ticker.remove(tick);
      lenis.destroy();
      ScrollTrigger.update();
    };
  }, [motionOff, low]);

  return null;
}

export { gsap, ScrollTrigger };

"use client";

import React, { Component, Suspense, useEffect, useRef, useState } from "react";
import { usePerf } from "../perf/PerfProvider";

interface StageBoundaryProps {
  fallback: React.ReactNode;
  children: React.ReactNode;
}

interface StageBoundaryState {
  failed: boolean;
}

class StageBoundary extends Component<StageBoundaryProps, StageBoundaryState> {
  constructor(props: StageBoundaryProps) {
    super(props);
    this.state = { failed: false };
  }

  static getDerivedStateFromError() {
    return { failed: true };
  }

  render() {
    if (this.state.failed) return this.props.fallback;
    return this.props.children;
  }
}

interface LazyStageProps {
  scene: React.ComponentType<{ onReady?: () => void; [key: string]: unknown }>;
  fallback: string;
  label: string;
  sceneProps?: Record<string, unknown>;
  className?: string;
}

export function LazyStage({
  scene: Scene,
  fallback,
  label,
  sceneProps = {},
  className = "",
}: LazyStageProps) {
  const { motionOff } = usePerf();
  const ref = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    if (motionOff) {
      setVisible(false);
      setReady(false);
      return undefined;
    }
    const node = ref.current;
    if (!node || typeof IntersectionObserver === "undefined") {
      setVisible(true);
      return undefined;
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        setVisible(entry.isIntersecting);
        if (!entry.isIntersecting) setReady(false);
      },
      { rootMargin: "200px" }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [motionOff]);

  return (
    <div ref={ref} className={`relative w-full h-full min-h-[420px] bg-[#08090C] overflow-hidden ${className}`}>
      {/* Fallback image */}
      <img
        src={fallback}
        alt=""
        className={`absolute inset-0 w-full h-full object-contain pointer-events-none transition-opacity duration-700 ${
          ready ? "opacity-0" : "opacity-40"
        }`}
      />
      <p className="sr-only">
        {label} Decorative 3D graphic. The description is in the section heading beside it.
      </p>
      {visible && (
        <StageBoundary fallback={null}>
          <Suspense fallback={null}>
            <div className="absolute inset-0 w-full h-full" aria-hidden="true">
              <Scene onReady={() => setReady(true)} {...sceneProps} />
            </div>
          </Suspense>
        </StageBoundary>
      )}
    </div>
  );
}

