    <button
      ref={btnRef as React.Ref<HTMLButtonElement>}
      type="button"
      onMouseMove={handleMouseMove}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={onClick}
      style={transformStyle}
      className={sharedClasses}
    >
      {content}
    </button>
  );
}

