                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Instruction Summary Footer */}
            <div className="pt-4 mt-4 border-t border-[#1C202B] flex flex-wrap items-center justify-between text-[11px] font-mono text-[#8E9AA8]">
