/* Scramjet Crosshair Hover Shear (#29) */
.scramjet-crosshair {
  position: fixed;
  top: 0;
  left: 0;
  width: 26px;
  height: 26px;
  border: 1px solid rgba(255, 119, 0, 0.65);
  border-radius: 50%;
  pointer-events: none;
  z-index: 9999;
  transform: translate(-50%, -50%);
  transition: opacity 0.2s ease, border-color 0.2s ease;
  box-shadow: 0 0 10px rgba(255, 119, 0, 0.3);
}

.scramjet-crosshair::before,
.scramjet-crosshair::after {
  content: '';
  position: absolute;
  background: rgba(255, 119, 0, 0.85);
}

.scramjet-crosshair::before {
  top: 50%;
  left: -5px;
  right: -5px;
  height: 1px;
  transform: translateY(-50%);
}

.scramjet-crosshair::after {
  left: 50%;
  top: -5px;
  bottom: -5px;
  width: 1px;
  transform: translateX(-50%);
}

import { chromium } from "playwright";

async function run() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
