"use client";

import React, { useEffect, useRef, useState } from "react";

/** Fades/slides children in once when scrolled into view. */
export function Reveal({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node || typeof IntersectionObserver === "undefined") {
      setShown(true);
      return;
    }
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setShown(true);
          io.disconnect();
        }
      },
      { threshold: 0.15, rootMargin: "0px 0px -8% 0px" }
    );
    io.observe(node);
    return () => io.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      className={`transition-all duration-[900ms] ease-[cubic-bezier(0.16,1,0.3,1)] ${
        shown ? "opacity-100 translate-y-0 blur-0" : "opacity-0 translate-y-10 blur-sm"
      } ${className}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {children}
    </div>
  );
}

/** Big editorial chapter that sits between animation sections. */
export function Chapter({
  number,
  kicker,
  title,
  accent,
  body,
  points,
}: {
  number: string;
  kicker: string;
  title: string;
  accent: string;
  body: string;
  points?: { label: string; text: string }[];
}) {
  return (
    <section className="relative max-w-6xl mx-auto px-4 sm:px-6 py-28 sm:py-40">
      <div
        aria-hidden
        className="absolute left-2 sm:left-6 top-10 text-[120px] sm:text-[220px] font-black leading-none text-transparent select-none pointer-events-none"
        style={{ WebkitTextStroke: "1px rgba(255,119,0,0.14)" }}
      >
        {number}
      </div>

      <div className="relative grid grid-cols-1 lg:grid-cols-12 gap-10 items-start">
        <div className="lg:col-span-7 space-y-6">
          <Reveal>
            <span className="inline-flex items-center gap-2 text-[11px] font-mono font-bold tracking-[0.25em] uppercase text-[#FF7700]">
              <span className="w-8 h-px bg-[#FF7700]" />
              {kicker}
            </span>
          </Reveal>
          <Reveal delay={100}>
            <h2 className="text-4xl sm:text-6xl font-extrabold tracking-tight leading-[1.04] text-[#F8FAFC]">
              {title}{" "}
              <span className="bg-gradient-to-r from-[#FF3E00] via-[#FF7700] to-[#FFA040] bg-clip-text text-transparent">
                {accent}
              </span>
            </h2>
          </Reveal>
          <Reveal delay={200}>
            <p className="text-base sm:text-lg text-[#8E9AA8] leading-relaxed max-w-xl">{body}</p>
          </Reveal>
        </div>

        {points && (
          <div className="lg:col-span-5 space-y-3 lg:pt-14">
            {points.map((p, i) => (
              <Reveal key={p.label} delay={150 + i * 120}>
                <div className="group p-4 rounded-xl border border-[#1C202B] bg-[#0A0C10]/80 hover:border-[#FF3E00]/50 transition-colors">
                  <div className="text-[10px] font-mono uppercase tracking-widest text-[#FF7700] mb-1">
                    {p.label}
                  </div>
                  <div className="text-sm text-[#C5CCD6] leading-relaxed">{p.text}</div>
                </div>
              </Reveal>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

function CountUp({ to, suffix = "", prefix = "", decimals = 0 }: { to: number; suffix?: string; prefix?: string; decimals?: number }) {
  const ref = useRef<HTMLSpanElement>(null);
  const [val, setVal] = useState(0);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    let raf = 0;
    const io = new IntersectionObserver(([e]) => {
      if (!e.isIntersecting) return;
      io.disconnect();
      const start = performance.now();
      const dur = 1600;
      const tick = (t: number) => {
        const p = Math.min(1, (t - start) / dur);
        setVal(to * (1 - Math.pow(1 - p, 3)));
        if (p < 1) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    });
    io.observe(node);
    return () => {
      io.disconnect();
      cancelAnimationFrame(raf);
    };
  }, [to]);

  return (
    <span ref={ref}>
      {prefix}
      {val.toFixed(decimals)}
      {suffix}
    </span>
  );
}

export function StatsStrip() {
  const stats = [
    { to: 3.5, suffix: "%", decimals: 1, label: "Platform fee", sub: "vs 5.0% elsewhere" },
    { to: 0.01, prefix: "", suffix: " SOL", decimals: 2, label: "Min sub-wallet", sub: "10x lower lockup" },
    { to: 12, suffix: "", decimals: 0, label: "Launchpads", sub: "one interface" },
    { to: 24, suffix: "", decimals: 0, label: "Sub-wallets", sub: "per Block-0 bundle" },
  ];
  return (
    <section className="max-w-6xl mx-auto px-4 sm:px-6 py-20">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-px rounded-2xl overflow-hidden border border-[#1C202B] bg-[#1C202B]">
        {stats.map((s, i) => (
          <Reveal key={s.label} delay={i * 100} className="bg-[#07080B]">
            <div className="p-6 sm:p-8 text-center">
              <div className="text-4xl sm:text-5xl font-extrabold font-mono text-[#FF7700]">
                <CountUp to={s.to} suffix={s.suffix} prefix={s.prefix} decimals={s.decimals} />
              </div>
              <div className="mt-2 text-xs font-bold uppercase tracking-widest text-[#F8FAFC]">{s.label}</div>
              <div className="text-[11px] font-mono text-[#717686] mt-1">{s.sub}</div>
            </div>
          </Reveal>
        ))}
      </div>
    </section>
  );
}

export function Marquee({ items }: { items: string[] }) {
  const row = [...items, ...items];
  return (
    <div className="relative overflow-hidden border-y border-[#14161F] bg-[#0A0B0E] py-4" aria-hidden>
      <div className="flex w-max gap-10 animate-marquee text-xs font-mono font-bold uppercase tracking-[0.3em] text-[#4A5568]">
        {row.map((t, i) => (
          <span key={i} className="flex items-center gap-10 whitespace-nowrap">
            {t}
            <span className="text-[#FF7700]">&#9670;</span>
          </span>
        ))}
      </div>
    </div>
  );
}

export function HowItWorks() {
  const steps = [
    { n: "01", t: "Connect", d: "Link a Solana wallet. Keys for sub-wallets are generated inside a Turnkey enclave, never in your browser." },
    { n: "02", t: "Configure", d: "Pick a launchpad, set your token details, choose Block-0, Organic or Manual mode and your sniper guard." },
    { n: "03", t: "Fund quietly", d: "Ghost Funder routes SOL through relay wallets with jittered amounts so no single parent links your holders." },
    { n: "04", t: "Ignite", d: "Deploy and every buy land together in one Jito bundle. Rent is reclaimed automatically afterwards." },
  ];
  return (
    <section className="max-w-6xl mx-auto px-4 sm:px-6 py-28">
      <Reveal>
        <div className="text-center space-y-3 mb-14">
          <span className="text-[11px] font-mono font-bold tracking-[0.25em] uppercase text-[#FF7700]">How it works</span>
          <h2 className="text-4xl sm:text-5xl font-extrabold tracking-tight text-[#F8FAFC]">From idea to Block-0 in four moves.</h2>
        </div>
      </Reveal>
      <div className="relative grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="hidden md:block absolute top-9 left-[12%] right-[12%] h-px bg-gradient-to-r from-transparent via-[#FF3E00]/50 to-transparent" />
        {steps.map((s, i) => (
          <Reveal key={s.n} delay={i * 130}>
            <div className="relative p-5 rounded-2xl border border-[#1C202B] bg-[#0A0C10] h-full hover:-translate-y-1 hover:border-[#FF3E00]/50 transition-all duration-300">
              <div className="w-10 h-10 rounded-full bg-[#FF3E00] text-black font-mono font-black text-sm flex items-center justify-center mb-4 shadow-[0_0_20px_rgba(255,62,0,0.45)]">
                {s.n}
              </div>
              <h3 className="text-lg font-bold text-[#F8FAFC] mb-1.5">{s.t}</h3>
              <p className="text-sm text-[#8E9AA8] leading-relaxed">{s.d}</p>
            </div>
          </Reveal>
        ))}
      </div>
    </section>
  );
}

